    #[test]
    fn ha_enabled_clears_timer() {
        let now = std::time::Instant::now();
        // Even with a timer running, HA being enabled clears it.
        let since = now - Duration::from_secs(3600);
        assert_eq!(
            ha_check_decision(
                Some(true),
                Some(since),
                now,
                HA_DISARMED_ALERT_AFTER,
                None,
                DEGRADED_REALERT_AFTER
            ),
            HaCheckAction::ClearTimer
        );
    }

    #[test]
