    // Stranded-former-master decision. Aliases keep the many-arg calls short.
    const SG: Duration = STRANDED_MASTER_GRACE;
    const SR: Duration = STRANDED_MASTER_RETRY_AFTER;
    const SC: u32 = STRANDED_MASTER_RESTART_CAP;
    const SFC: u32 = STRANDED_MASTER_FORCE_RESET_CAP;
    const SCG: Duration = SLAVE_REJOIN_CLEAR_GRACE;

    #[test]
    fn stranded_master_all_signals_starts_timer_then_restarts() {
        let now = std::time::Instant::now();
        // I read as master, the peer is healthy on the link but not live in my
        // pool, and I run no VMs.
        assert_eq!(
            stranded_master_decision(
                true,
                true,
                true,
                Some(false),
                false,
                false,
                Some(0),
                None,
                None,
                0,
                now,
                SG,
                SR,
                SC,
                SFC
            ),
            StrandedAction::StartTimer
        );
        // Past the grace with no prior restart: fire the first toolstack-restart.
        let since = now - SG - Duration::from_secs(1);
        assert_eq!(
            stranded_master_decision(
                true,
                true,
                true,
                Some(false),
                false,
                false,
                Some(0),
                Some(since),
                None,
                0,
                now,
                SG,
                SR,
                SC,
                SFC
            ),
            StrandedAction::Restart
        );
    }

    #[test]
    fn stranded_master_liveset_member_never_restarts() {
        // A joined, fencing-armed XHA liveset member that reads itself master
        // from a stale pool.conf must not toolstack-restart to yield (that
        // livelocks): it joined under the elected master, so XAPI reconciles the
        // stale role itself. The signals that fire Restart for a non-member must
        // be inert here, on both triggers (peer not live, own xapi hung).
        let now = std::time::Instant::now();
        let since = now - SG - Duration::from_secs(1);
        // Control: identical inputs with defer_rejoin_selfheal=false give Restart.
        assert_eq!(
            stranded_master_decision(
                true,
                true,
                true,
                Some(false),
                false,
                false,
                Some(0),
                Some(since),
                None,
                0,
                now,
                SG,
                SR,
                SC,
                SFC
            ),
            StrandedAction::Restart
        );
        // With defer_rejoin_selfheal=true the strand is suppressed (timer clears).
        assert_eq!(
            stranded_master_decision(
                true,
                true,
                true,
                Some(false),
                false,
                true,
                Some(0),
                Some(since),
                None,
                0,
                now,
                SG,
                SR,
                SC,
                SFC
            ),
            StrandedAction::Clear
        );
        // Also suppressed on the hung-XAPI trigger (peer_live_in_pool inert, xapi_hung).
        assert_eq!(
            stranded_master_decision(
                true,
                true,
                true,
                None,
                true,
                true,
                Some(0),
                Some(since),
                None,
                0,
                now,
                SG,
                SR,
                SC,
                SFC
            ),
            StrandedAction::Clear
        );
        // And before any timer starts (since=None): never even arms.
        assert_eq!(
            stranded_master_decision(
                true,
                true,
                true,
                Some(false),
                false,
                true,
                Some(0),
                None,
                None,
                0,
                now,
                SG,
                SR,
                SC,
                SFC
            ),
            StrandedAction::Idle
        );
    }

    #[test]
    fn stranded_master_within_grace_idles() {
        let now = std::time::Instant::now();
        let since = now - Duration::from_secs(30); // under the 120s grace: could be a booting peer
        assert_eq!(
            stranded_master_decision(
                true,
                true,
                true,
                Some(false),
                false,
                false,
                Some(0),
                Some(since),
                None,
                0,
                now,
                SG,
                SR,
                SC,
                SFC
            ),
            StrandedAction::Idle
        );
    }

    #[test]
    fn stranded_master_survivor_with_vms_never_matches() {
        // The real survivor holds the VMs (vms != 0), so it is never picked as
        // the stranded loser, even with identical master and peer signals.
        let now = std::time::Instant::now();
        let since = now - SG - Duration::from_secs(1);
        assert_eq!(
            stranded_master_decision(
                true,
                true,
                true,
                Some(false),
                false,
                false,
                Some(2),
                Some(since),
                None,
                0,
                now,
                SG,
                SR,
                SC,
                SFC
            ),
            StrandedAction::Clear
        );
    }

