    #[test]
    fn ha_deadlock_exit_gates_on_every_precondition() {
        // The HA-deadlock exit fires only on a data-safe, stable dual-master
        // where this node is the yielder. Any missing gate falls back to hold
        // and alert.
        let now = std::time::Instant::now();
        let past = now - Duration::from_secs(600);
        let cf = Duration::from_secs(60);
        let rt = Duration::from_secs(120);
        let d = StateMachine::ha_deadlock_exit_decision;
        // all gates met: Act
        assert_eq!(
            d(true, true, true, Some(past), None, now, cf, rt),
            HaDeadlockAction::Act
        );
        // storage not provably safe: Hold (the control-plane-only gate)
        assert_eq!(
            d(false, true, true, Some(past), None, now, cf, rt),
            HaDeadlockAction::Hold
        );
        // not a dual-master: Hold
        assert_eq!(
            d(true, false, true, Some(past), None, now, cf, rt),
            HaDeadlockAction::Hold
        );
        // not the yielder (never demote the continuous survivor): Hold
        assert_eq!(
            d(true, true, false, Some(past), None, now, cf, rt),
            HaDeadlockAction::Hold
        );
        // no stability timer yet: Hold
        assert_eq!(
            d(true, true, true, None, None, now, cf, rt),
            HaDeadlockAction::Hold
        );
        // within the confirm window: Hold (must be stable, not a transient)
        assert_eq!(
            d(true, true, true, Some(now), None, now, cf, rt),
            HaDeadlockAction::Hold
        );
        // acted recently: Hold (rate limit, do not thrash the toolstack)
        let recent2 = now - Duration::from_secs(1);
        assert_eq!(
            d(true, true, true, Some(past), Some(recent2), now, cf, rt),
            HaDeadlockAction::Hold
        );
    }

    #[test]
    fn returned_yielder_is_only_the_recently_rejoined_node() {
        // The survivor never runs isolated_rejoin, so it is never the yielder
        // (demoting it is the harmful case). Only a node that returned from
        // isolation within the window qualifies.
        let now = std::time::Instant::now();
        let w = Duration::from_secs(30 * 60);
        assert!(!is_returned_yielder(None, now, w)); // survivor
        assert!(is_returned_yielder(
            Some(now - Duration::from_secs(60)),
            now,
            w
        )); // just returned
        assert!(!is_returned_yielder(
            Some(now - Duration::from_secs(31 * 60)),
            now,
            w
        )); // expired
    }

    #[test]
    fn dual_master_present_local_signal_covers_hung_xapi_standdown() {
        // The returned yielder must detect the dual-master from local signals, so
        // the HA-deadlock exit fires after an isolated-master stand-down, where on
        // rejoin its own xapi is wedged and the forwarded peer_host_live is inert.
        // Working-xe fork: the peer reads not live in my pool DB.
        assert!(dual_master_present(true, true, true, false));
        // Hung-xapi fork: peer_not_live is inert (false), but xapi_hung stands
        // in, so it is still detected. Without it the exit never yields on a
        // hung-xapi rejoin.
        assert!(dual_master_present(true, true, false, true));
        // Healthy pool: I read master, peer healthy, no fork signal (peer is a
        // live member and my xapi answers): not a dual-master, never yield.
        assert!(!dual_master_present(true, true, false, false));
        // Not master, or peer not healthy: never a dual-master.
        assert!(!dual_master_present(false, true, true, true));
        assert!(!dual_master_present(true, false, true, true));
    }

    #[test]
    fn ha_deadlock_exit_acts_on_hung_xapi_fork_via_local_signal() {
        // A returned yielder whose fork is shown only by xapi_hung still reaches
        // Act once confirmed (data-safe and stable).
        let now = std::time::Instant::now();
        let past = now - Duration::from_secs(600);
        let cf = Duration::from_secs(90);
        let rt = Duration::from_secs(300);
        let dual = dual_master_present(true, true, false, true); // hung-xapi fork
        assert!(dual);
        assert_eq!(
            StateMachine::ha_deadlock_exit_decision(
                true,
                dual,
                true,
                Some(past),
                None,
                now,
                cf,
                rt
            ),
            HaDeadlockAction::Act
        );
    }

