    #[test]
    fn slave_rejoin_liveset_member_never_restarts() {
        // A slave whose slave-to-master XAPI link carries live HA heartbeats
        // (last_xha_online plus local HA armed, hence defer_rejoin_selfheal) is
        // not wedged even when a forwarded xe read flaps unreadable: the path
        // works, and the flap is usually contention from our own earlier
        // toolstack restart. Restarting again livelocks the node, so never restart.
        let now = std::time::Instant::now();
        let since = now - SG - Duration::from_secs(1);
        // Control: unreadable xapi and not a liveset member gives Restart.
        assert_eq!(
            slave_rejoin_decision(
                true,
                true,
                true,
                false,
                false,
                Some(since),
                None,
                0,
                None,
                now,
                SG,
                SR,
                SC,
                SCG
            ),
            StrandedAction::Restart
        );
        // With defer_rejoin_selfheal=true the wedge is suppressed (timer clears).
        assert_eq!(
            slave_rejoin_decision(
                true,
                true,
                true,
                false,
                true,
                Some(since),
                None,
                0,
                None,
                now,
                SG,
                SR,
                SC,
                SCG
            ),
            StrandedAction::Clear
        );
        // And before any timer starts (since=None): never even arms.
        assert_eq!(
            slave_rejoin_decision(
                true, true, true, false, true, None, None, 0, None, now, SG, SR, SC, SCG
            ),
            StrandedAction::Idle
        );
    }

