    #[test]
    fn slave_rejoin_clears_only_after_sustained_recovery() {
        // A single not-wedged tick must not clear the restart cap, or a flapping
        // local xapi (up, then re-wedged) resets the cap between restarts and
        // drives unbounded toolstack churn with no give-up alert.
        let now = std::time::Instant::now();
        let since = now - SG - Duration::from_secs(1);
        // Production shape: the wedge lifts because xapi reads live again. The
        // caller forces peer_is_master=false once xapi is readable (it can only
        // probe it while unreadable), so the recovery tick is
        // (is_slave=true, peer_alive=true, peer_is_master=false, xapi_readable=true).
        // The debounce must engage on this shape, or it is dead code.
        // Wedge just lifted (healthy_since not yet armed): hold, do not clear.
        assert_eq!(
            slave_rejoin_decision(
                true,
                true,
                false,
                true,
                false,
                Some(since),
                None,
                0,
                None,
                now,
                SG,
                SR,
                SC,
                SCG
            ),
            StrandedAction::Idle
        );
        let fresh = now - SCG + Duration::from_secs(1); // healthy, but < clear_grace
        assert_eq!(
            slave_rejoin_decision(
                true,
                true,
                false,
                true,
                false,
                Some(since),
                None,
                0,
                Some(fresh),
                now,
                SG,
                SR,
                SC,
                SCG
            ),
            StrandedAction::Idle
        );
        // Healthy continuously for at least clear_grace: now safe to clear.
        let sustained = now - SCG - Duration::from_secs(1);
        assert_eq!(
            slave_rejoin_decision(
                true,
                true,
                false,
                true,
                false,
                Some(since),
                None,
                0,
                Some(sustained),
                now,
                SG,
                SR,
                SC,
                SCG
            ),
            StrandedAction::Clear
        );
    }

    #[test]
    fn slave_rejoin_flap_never_clears_the_cap() {
        // Starvation case: xapi flaps readable then re-wedges before the clear
        // grace elapses. Each re-wedge resets healthy_since (caller-managed), so
        // the not-wedged ticks in between only return Idle, and the cap and the
        // eventual GiveUp alert survive the flapping.
        let now = std::time::Instant::now();
        let since = now - SG - Duration::from_secs(1);
        // At the cap, still wedged: GiveUp (the alert that must not starve).
        assert_eq!(
            slave_rejoin_decision(
                true,
                true,
                true,
                false,
                false,
                Some(since),
                Some(now - SR - Duration::from_secs(1)),
                SC,
                None,
                now,
                SG,
                SR,
                SC,
                SCG
            ),
            StrandedAction::GiveUp
        );
        // A brief readable blip (production shape: peer_is_master forced false
        // when xapi reads live) with a freshly armed healthy_since does not clear.
        let blip = now - Duration::from_secs(1);
        assert_eq!(
            slave_rejoin_decision(
                true,
                true,
                false,
                true,
                false,
                Some(since),
                None,
                SC,
                Some(blip),
                now,
                SG,
                SR,
                SC,
                SCG
            ),
            StrandedAction::Idle
        );
    }

    #[test]
    fn isolated_master_reset_requires_sustained_recovery() {
        use IsolatedMasterReset::*;
        let now = std::time::Instant::now();
        let g = ISOLATED_MASTER_CLEAR_GRACE;
        // Topology change (no longer follows the peer): clear immediately.
        assert_eq!(
            isolated_master_reset_decision(false, false, None, now, g, false),
            Clear
        );
        assert_eq!(
            isolated_master_reset_decision(false, true, Some(now), now, g, false),
            Clear
        );
        // Wedge live (follows peer, xe dead): reset the debounce, keep the clock.
        assert_eq!(
            isolated_master_reset_decision(true, true, None, now, g, false),
            Wedged
        );
        assert_eq!(
            isolated_master_reset_decision(true, true, Some(now - g), now, g, false),
            Wedged
        );
        // xe just answered (follows peer, not xe_dead), debounce not yet armed.
        assert_eq!(
            isolated_master_reset_decision(true, false, None, now, g, true),
            ArmDebounce
        );
        // xe alive but not yet sustained past the grace: hold the clock, do not
        // reset it; a transient xe flip from a sibling toolstack must not starve
        // the alert.
        let fresh = now - g + Duration::from_secs(1);
        assert_eq!(
            isolated_master_reset_decision(true, false, Some(fresh), now, g, true),
            HoldDebounce
        );
        // xe answered continuously past the grace: safe to clear.
        let sustained = now - g - Duration::from_secs(1);
        assert_eq!(
            isolated_master_reset_decision(true, false, Some(sustained), now, g, true),
            Clear
        );
        // Flap sequence: transient recovery (Arm/Hold) never reaches Clear, and a
        // re-wedge returns Wedged (the caller resets recovered_since), so the
        // maturity clock survives a flapping local xapi and the alert still matures.
        assert_ne!(
            isolated_master_reset_decision(true, false, Some(fresh), now, g, true),
            Clear
        );
        assert_eq!(
            isolated_master_reset_decision(true, true, Some(fresh), now, g, false),
            Wedged
        );
        // A healthy follower that never wedged (wedge_tracked=false) stays Idle.
        // ArmDebounce here would re-log `isolated_master_clock_held` every
        // clear_grace indefinitely. The same inputs with a tracked wedge still
        // ArmDebounce (the real recovery hold).
        assert_eq!(
            isolated_master_reset_decision(true, false, None, now, g, false),
            Idle
        );
        assert_eq!(
            isolated_master_reset_decision(true, false, None, now, g, true),
            ArmDebounce
        );
    }

    #[test]
    fn isolated_master_reset_full_lifecycle_logs_once_then_idles() {
        use IsolatedMasterReset::*;
        let now = std::time::Instant::now();
        let g = ISOLATED_MASTER_CLEAR_GRACE;
        // A wedge then recovery, driving `wedge_tracked` and `recovered_since` as
        // the caller would, must ArmDebounce (log) once, then reach Idle.
        // (1) wedge live: Wedged; caller arms isolated_master_since
        //     (wedge_tracked=true), recovered_since stays None.
        assert_eq!(
            isolated_master_reset_decision(true, true, None, now, g, false),
            Wedged
        );
        // (2) xe recovers, clock armed: ArmDebounce (logs once); caller sets
        //     recovered_since.
        assert_eq!(
            isolated_master_reset_decision(true, false, None, now, g, true),
            ArmDebounce
        );
        // (3) within grace: HoldDebounce (no log).
        assert_eq!(
            isolated_master_reset_decision(true, false, Some(now), now, g, true),
            HoldDebounce
        );
        // (4) past grace: Clear; caller resets both isolated_master_since and
        //     recovered_since.
        assert_eq!(
            isolated_master_reset_decision(
                true,
                false,
                Some(now - g - Duration::from_secs(1)),
                now,
                g,
                true
            ),
            Clear
        );
        // (5) next tick: nothing armed, Idle (quiet). No repeated re-log.
        assert_eq!(
            isolated_master_reset_decision(true, false, None, now, g, false),
            Idle
        );
    }

    #[test]
    fn should_defer_rejoin_selfheal_gate() {
        // Defer when this node is an XHA liveset member...
        assert!(should_defer_rejoin_selfheal(
            true, false, false, false, false
        ));
        // ...or the readmission watchdog is mid-rejoin (any marker set).
        assert!(should_defer_rejoin_selfheal(
            false, true, false, false, false
        ));
        assert!(should_defer_rejoin_selfheal(
            false, false, true, false, false
        ));
        assert!(should_defer_rejoin_selfheal(
            false, false, false, true, false
        ));
        assert!(should_defer_rejoin_selfheal(
            false, false, false, false, true
        ));
        // Out-of-liveset wedge, no readmission in flight: fire the self-heals.
        // On an HA-off pool the reaper pins `last_xha_online=Some(true)`, but
        // `check_ha_readmission` sets `xha_liveset_member=false` in the HA-off
        // branch, so the gate receives false and does not suppress: HA-off
        // recovery self-heals stay active.
        assert!(!should_defer_rejoin_selfheal(
            false, false, false, false, false
        ));
    }

    #[test]
    fn readmission_flap_alert_timing() {
        let now = std::time::Instant::now();
        let grace = READMISSION_FLAP_ALERT_AFTER;
        let realert = DEGRADED_REALERT_AFTER;
        // Within grace: no alert (clean readmissions settle in a few minutes).
        assert!(!readmission_flap_should_alert(
            now, None, now, grace, realert
        ));
        let past = now - grace - Duration::from_secs(1);
        // Past grace, never alerted: alert.
        assert!(readmission_flap_should_alert(
            past, None, now, grace, realert
        ));
        // Past grace but alerted recently: hold (no re-alert spam).
        assert!(!readmission_flap_should_alert(
            past,
            Some(now - Duration::from_secs(10)),
            now,
            grace,
            realert
        ));
        // Past grace and re-alert window elapsed: alert again.
        assert!(readmission_flap_should_alert(
            past,
            Some(now - realert - Duration::from_secs(1)),
            now,
            grace,
            realert
        ));
    }

    #[test]
    fn master_client_isolated_verdict_arbitrated_requires_confirmed_down() {
        use crate::peer_signal::PeerGateway;
        // On arbitrated pools only a confirmed beacon Down engages the wedge, so
        // xe_dead can be true (and the maturity clock arm) only when the master
        // really is cut off from clients.
        assert!(master_client_isolated_verdict(true, PeerGateway::Down));
        // A reachable, healthy master never engages it, so a flapping forwarded
        // is_ha_enabled() read cannot pin the clock, and the per-tick pool-list
        // forward is skipped.
        assert!(!master_client_isolated_verdict(true, PeerGateway::Up));
        assert!(!master_client_isolated_verdict(true, PeerGateway::Unknown));
        assert!(!master_client_isolated_verdict(
            true,
            PeerGateway::Unreachable
        ));
    }

    #[test]
    fn master_client_isolated_verdict_fate_shared_is_inert() {
        use crate::peer_signal::PeerGateway;
        // Fate-shared has no direct-link beacon (single replication path), so
        // the gate must not suppress the forwarded read, whatever the (unused)
        // beacon value.
        for gw in [
            PeerGateway::Up,
            PeerGateway::Down,
            PeerGateway::Unknown,
            PeerGateway::Unreachable,
        ] {
            assert!(master_client_isolated_verdict(false, gw));
        }
    }

    // --- Wrongly-demoted-survivor decision. ---
    const DG: Duration = DEMOTED_SURVIVOR_GRACE;
    const DR: Duration = DEMOTED_SURVIVOR_RETRY_AFTER;
    const DC: u32 = DEMOTED_SURVIVOR_CAP;

    #[test]
    fn demoted_survivor_inverted_starts_timer_then_reasserts() {
        let now = std::time::Instant::now();
        // Slave of the peer, I am UpToDate, the peer is Connected but stale and
        // reachable.
        assert_eq!(
            demoted_survivor_decision(
                true, true, true, true, false, None, None, 0, now, DG, DR, DC
            ),
            StrandedAction::StartTimer
        );
        let since = now - DG - Duration::from_secs(1);
        assert_eq!(
            demoted_survivor_decision(
                true,
                true,
                true,
                true,
                false,
                Some(since),
                None,
                0,
                now,
                DG,
                DR,
                DC
            ),
            StrandedAction::Restart
        );
    }

    #[test]
    fn demoted_survivor_peer_uptodate_never_fires() {
        // Normal operation: a slave whose master is UpToDate (peer_stale=false) is
        // not inverted and must never re-assert.
        let now = std::time::Instant::now();
        assert_eq!(
            demoted_survivor_decision(
                true, true, false, true, false, None, None, 0, now, DG, DR, DC
            ),
            StrandedAction::Idle
        );
    }

    #[test]
    fn demoted_survivor_not_uptodate_never_fires() {
        // A node that is not the good copy never re-asserts mastership.
        let now = std::time::Instant::now();
        assert_eq!(
            demoted_survivor_decision(
                true, false, true, true, false, None, None, 0, now, DG, DR, DC
            ),
            StrandedAction::Idle
        );
    }

    #[test]
    fn demoted_survivor_not_slave_or_unreachable_never_fires() {
        let now = std::time::Instant::now();
        // Not a slave of the peer (e.g. I am the master, or slave-of-self).
        assert_eq!(
            demoted_survivor_decision(
                false, true, true, true, false, None, None, 0, now, DG, DR, DC
            ),
            StrandedAction::Idle
        );
        // Peer unreachable on management: the transition's recover-slaves cannot run.
        assert_eq!(
            demoted_survivor_decision(
                true, true, true, false, false, None, None, 0, now, DG, DR, DC
            ),
            StrandedAction::Idle
        );
    }

    #[test]
    fn demoted_survivor_respects_cadence_and_cap() {
        let now = std::time::Instant::now();
        let since = now - DG - Duration::from_secs(1);
        let recent = now - Duration::from_secs(30);
        assert_eq!(
            demoted_survivor_decision(
                true,
                true,
                true,
                true,
                false,
                Some(since),
                Some(recent),
                1,
                now,
                DG,
                DR,
                DC
            ),
            StrandedAction::Idle
        );
        let old = now - DR - Duration::from_secs(1);
        assert_eq!(
            demoted_survivor_decision(
                true,
                true,
                true,
                true,
                false,
                Some(since),
                Some(old),
                1,
                now,
                DG,
                DR,
                DC
            ),
            StrandedAction::Restart
        );
        assert_eq!(
            demoted_survivor_decision(
                true,
                true,
                true,
                true,
                false,
                Some(since),
                Some(old),
                DC,
                now,
                DG,
                DR,
                DC
            ),
            StrandedAction::GiveUp
        );
    }

    #[test]
    fn demoted_survivor_clears_when_resolved() {
        let now = std::time::Instant::now();
        let since = now - DG - Duration::from_secs(1);
        // Timer was running; peer resynced to UpToDate (no longer inverted): clear.
        assert_eq!(
            demoted_survivor_decision(
                true,
                true,
                false,
                true,
                false,
                Some(since),
                None,
                0,
                now,
                DG,
                DR,
                DC
            ),
            StrandedAction::Clear
        );
    }

    #[test]
    fn demoted_survivor_actively_resolving_never_fires() {
        // All inversion signals true, but the stale peer is actively being resolved
        // (progressing resync or an isolated-master stand-down): transient, hold.
        let now = std::time::Instant::now();
        assert_eq!(
            demoted_survivor_decision(true, true, true, true, true, None, None, 0, now, DG, DR, DC),
            StrandedAction::Idle
        );
        // Even past the grace, an actively-resolving inversion never re-asserts;
        // if a timer was running it clears (the state is not stuck).
        let since = now - DG - Duration::from_secs(1);
        assert_eq!(
            demoted_survivor_decision(
                true,
                true,
                true,
                true,
                true,
                Some(since),
                None,
                0,
                now,
                DG,
                DR,
                DC
            ),
            StrandedAction::Clear
        );
    }

