    #[test]
    fn failback_request_bypasses_hold_and_latch() {
        let now = std::time::Instant::now();
        // Latched, unstable, auto off: the explicit request still dances (safety
        // gates are enforced later, at dance time).
        assert_eq!(
            failback_decision(true, true, false, true, true, 5, None, now),
            FailbackAction::Dance
        );
    }

    #[test]
    fn failback_blocked_states() {
        let now = std::time::Instant::now();
        assert_eq!(
            failback_decision(true, true, true, false, true, 3, Some(now), now),
            FailbackAction::Blocked(FailbackBlock::Latched)
        );
        assert_eq!(
            failback_decision(true, true, false, false, false, 0, Some(now), now),
            FailbackAction::Blocked(FailbackBlock::AutoDisabled)
        );
        assert_eq!(
            failback_decision(true, true, true, false, false, 0, None, now),
            FailbackAction::Blocked(FailbackBlock::Unstable)
        );
    }

    #[test]
    fn failback_escalating_hold_gates_the_dance() {
        let now = std::time::Instant::now();
        // Strike 0: 150 s hold. 100 s stable: still holding, about 50 s left.
        let since = now - Duration::from_secs(100);
        match failback_decision(true, true, true, false, false, 0, Some(since), now) {
            FailbackAction::Blocked(FailbackBlock::Holding(secs)) => {
                assert!((45..=55).contains(&secs), "expected ~50s left, got {secs}");
            }
            other => panic!("expected Holding, got {other:?}"),
        }
        // Past the strike-0 hold: dance.
        let since = now - FAILBACK_HOLDS[0] - Duration::from_secs(1);
        assert_eq!(
            failback_decision(true, true, true, false, false, 0, Some(since), now),
            FailbackAction::Dance
        );
        // Same stability at strike 1 is not enough (600 s hold).
        assert!(matches!(
            failback_decision(true, true, true, false, false, 1, Some(since), now),
            FailbackAction::Blocked(FailbackBlock::Holding(_))
        ));
        // Strikes beyond the table clamp to the longest hold.
        let since = now - FAILBACK_HOLDS[2] - Duration::from_secs(1);
        assert_eq!(
            failback_decision(true, true, true, false, false, 9, Some(since), now),
            FailbackAction::Dance
        );
    }

    #[test]
    fn defer_promote_only_while_connecting_and_not_yet_waited() {
        use crate::drbd::ConnectionState as C;
        // Connecting and not yet waited: the peer may be booting, hold off.
        assert!(should_defer_promote(C::Connecting, false));
        // Connecting but already waited once: the peer never arrived, promote
        // alone (no re-wait loop).
        assert!(!should_defer_promote(C::Connecting, true));
        // Connected: nothing to wait for.
        assert!(!should_defer_promote(C::Connected, false));
        // StandAlone / split-brain disconnect: owned by other paths, waiting
        // would not help.
        assert!(!should_defer_promote(C::StandAlone, false));
        assert!(!should_defer_promote(C::Unknown, false));
    }

    #[test]
    fn flap_storm_fires_at_threshold_once() {
        // Below both thresholds: individual events are normal, stay quiet.
        assert!(!flap_storm_decision(1, 0, false));
        assert!(!flap_storm_decision(2, 4, false));
        // Episode threshold reached: one bad cable, say so.
        assert!(flap_storm_decision(3, 0, false));
        assert!(flap_storm_decision(5, 0, false));
        // Disconnect-edge threshold: a marker persisting across rapid flaps
        // collapses many reseats into one episode, so raw edges also trigger.
        assert!(flap_storm_decision(1, 5, false));
        assert!(flap_storm_decision(0, 6, false));
        // Once per storm: the latch holds until the window empties.
        assert!(!flap_storm_decision(4, 6, true));
    }

    #[test]
    fn rejoin_rearm_fires_only_on_the_reachability_edge_once() {
        // The re-arm needs the unreachable-to-reachable edge: the peer was gone
        // and just came back, so a connect is imminent.
        assert!(rejoin_rearm_decision(Some(false), true, false));
        // First probe of the episode (no prior sample): never re-arm, the
        // node just had its full startup connection window.
        assert!(!rejoin_rearm_decision(None, true, false));
        // Level, not edge: a peer that pings but never connects must not
        // re-arm every tick (that would hold a lone survivor indefinitely).
        assert!(!rejoin_rearm_decision(Some(true), true, false));
        // Still unreachable: nothing changed.
        assert!(!rejoin_rearm_decision(Some(false), false, false));
        // One-shot per init episode: after a spent re-arm, the pre-existing
        // promote path takes over even on a fresh edge.
        assert!(!rejoin_rearm_decision(Some(false), true, true));
    }

    #[test]
    fn route_is_local_recognises_own_addresses_only() {
        assert!(route_is_local(
            "local 192.0.2.47 dev lo table local src 192.0.2.47 uid 0\n    cache <local>\n"
        ));
        assert!(!route_is_local(
            "192.0.2.49 dev xenbr0 src 192.0.2.47 uid 0\n    cache\n"
        ));
        assert!(!route_is_local(""));
    }

    #[test]
    fn boot_gate_holds_while_the_peer_is_alive_and_releases_after_the_grace() {
        let now = std::time::Instant::now();
        let grace = BOOT_GATE_CLEAR_GRACE;
        let ceil = BOOT_GATE_BOOTING_CEILING;
        let d = |ev, keeper, last, booting| {
            boot_gate_decision(ev, keeper, false, last, booting, now, grace, ceil)
        };
        let none = PeerLifeEvidence::default();
        let portal = PeerLifeEvidence {
            portal: true,
            ..none
        };
        let live = PeerLifeEvidence {
            liveset: Some(true),
            ..none
        };
        let beacon = PeerLifeEvidence {
            beacon: true,
            ..none
        };
        // The fenced former master reboots, replication is still cut, the peer
        // serves (portal answers) and is live in XHA. Never promote, on either
        // node, however long ago evidence was last seen.
        for ev in [
            portal,
            live,
            PeerLifeEvidence {
                portal: true,
                liveset: Some(true),
                beacon: true,
                peer_backing_gone: false,
            },
        ] {
            for keeper in [true, false] {
                assert_eq!(d(ev, keeper, None, None), BootGate::HoldPeerAlive);
                assert_eq!(
                    d(ev, keeper, Some(now - grace * 10), Some(now - ceil * 2)),
                    BootGate::HoldPeerAlive
                );
            }
        }
        // No evidence at all (lone host back from a full power loss, xhad not
        // joined): unchanged behaviour, the existing timers decide.
        assert_eq!(d(none, true, None, None), BootGate::Proceed);
        assert_eq!(d(none, false, None, None), BootGate::Proceed);
        // A readable liveset that shows the peer not live is not evidence of life.
        let gone = PeerLifeEvidence {
            liveset: Some(false),
            ..none
        };
        assert_eq!(d(gone, false, None, None), BootGate::Proceed);
        // Only the peer's daemon answers: both nodes are bringing storage up
        // with replication down. Exactly one side serves: the keeper.
        assert_eq!(d(beacon, true, None, None), BootGate::Proceed);
        assert_eq!(d(beacon, false, None, Some(now)), BootGate::HoldPeerBooting);
        // ... but not indefinitely: past the ceiling the non-keeper stops waiting on
        // a keeper that never serves (after the clear grace of its last hold).
        let past = Some(now - ceil - Duration::from_secs(1));
        assert_eq!(
            d(beacon, false, Some(now - Duration::from_secs(1)), past),
            BootGate::HoldClearing
        );
        assert_eq!(
            d(
                beacon,
                false,
                Some(now - grace - Duration::from_secs(1)),
                past
            ),
            BootGate::Proceed
        );
        // A keeper attesting it has no replica can never serve: no wait at all.
        let no_replica = PeerLifeEvidence {
            beacon: true,
            peer_backing_gone: true,
            ..none
        };
        assert_eq!(d(no_replica, false, None, Some(now)), BootGate::Proceed);
        assert_eq!(
            d(
                no_replica,
                false,
                Some(now - Duration::from_secs(5)),
                Some(now)
            ),
            BootGate::Proceed
        );
        // Evidence just vanished: a one-tick probe miss must not release an
        // immediate promote; the hold lasts the clear grace, on both nodes,
        // including a keeper that only still sees the beacon.
        let recent = Some(now - Duration::from_secs(5));
        assert_eq!(d(none, true, recent, None), BootGate::HoldClearing);
        assert_eq!(d(beacon, true, recent, None), BootGate::HoldClearing);
        // Grace elapsed with no evidence: back to the existing path.
        let stale = Some(now - grace - Duration::from_secs(1));
        assert_eq!(d(none, false, stale, None), BootGate::Proceed);
        assert_eq!(d(beacon, true, stale, None), BootGate::Proceed);
        assert_eq!(
            d(beacon, false, stale, Some(now)),
            BootGate::HoldPeerBooting
        );
    }

    #[test]
    fn a_peer_seen_serving_is_never_raced_by_a_solo_promote() {
        let now = std::time::Instant::now();
        let (grace, ceil) = (BOOT_GATE_CLEAR_GRACE, BOOT_GATE_BOOTING_CEILING);
        let none = PeerLifeEvidence::default();
        let beacon = PeerLifeEvidence {
            beacon: true,
            ..none
        };
        let no_replica = PeerLifeEvidence {
            beacon: true,
            peer_backing_gone: true,
            ..none
        };
        let long_ago = Some(now - grace * 100);
        for keeper in [true, false] {
            for ev in [none, beacon, no_replica] {
                // Evidence lapsed long ago, the booting ceiling passed: without
                // the memory the node would promote; with it, never.
                assert_ne!(
                    boot_gate_decision(
                        ev,
                        keeper,
                        false,
                        long_ago,
                        Some(now - ceil * 2),
                        now,
                        grace,
                        ceil
                    ),
                    BootGate::HoldPeerServedBefore
                );
                assert_eq!(
                    boot_gate_decision(
                        ev,
                        keeper,
                        true,
                        long_ago,
                        Some(now - ceil * 2),
                        now,
                        grace,
                        ceil
                    ),
                    BootGate::HoldPeerServedBefore,
                    "keeper={keeper} ev={ev:?}"
                );
            }
            // A peer visibly serving right now keeps the plain alive hold.
            let portal = PeerLifeEvidence {
                portal: true,
                ..none
            };
            assert_eq!(
                boot_gate_decision(portal, keeper, true, None, None, now, grace, ceil),
                BootGate::HoldPeerAlive
            );
        }
        // Never seen serving: the booting ceiling still releases a non-keeper.
        assert_eq!(
            boot_gate_decision(
                beacon,
                false,
                false,
                Some(now - grace - Duration::from_secs(1)),
                Some(now - ceil * 2),
                now,
                grace,
                ceil
            ),
            BootGate::Proceed
        );
        let (s, a) =
            boot_gate_served_before_texts(Duration::from_secs(600), "node-b", "twinstor-data");
        assert!(
            s.contains("may be behind")
                && a.contains("drbdadm primary --force twinstor-data")
                && a.contains("rejoins automatically"),
            "{s} / {a}"
        );
    }

    #[tokio::test(start_paused = true)]
    async fn peer_served_memory_survives_reboot_until_connected() {
        let drbd = std::sync::Arc::new(MockDrbd::new(starting_secondary()));
        *drbd.current_uuid.lock().unwrap() = Some(0xABCD_0000_0000_1230);
        let (mut sm, _) = StateMachine::new(
            test_config(),
            Box::new(ArcDrbd(drbd.clone())),
            Box::new(MockIscsi::new()),
        );
        let path = sm.peer_served_path.clone();
        sm.remember_peer_served().await;
        assert!(sm.peer_served_before && std::path::Path::new(&path).exists());
        let recorded = parse_peer_served(&std::fs::read_to_string(&path).unwrap());
        assert_eq!(
            recorded,
            Some(Some(0xABCD_0000_0000_1230)),
            "keyed by this node's generation"
        );
        // A restarted daemon or a rebooted host: the durable file is still
        // there and the generation unchanged, so the memory still applies.
        let (mut again, _) = StateMachine::new(
            test_config(),
            Box::new(ArcDrbd(drbd.clone())),
            Box::new(MockIscsi::new()),
        );
        again.peer_served_path = path.clone();
        again.peer_served_before = std::path::Path::new(&again.peer_served_path).exists();
        assert!(again.peer_served_before);
        assert!(peer_served_still_applies(
            recorded,
            Some(0xABCD_0000_0000_1230)
        ));
        // Connected (or this node serving) ends it, file included.
        again.forget_peer_served("connected");
        assert!(!again.peer_served_before && !std::path::Path::new(&path).exists());
    }

    #[test]
    fn wait_released_only_by_destroyed_backing_and_portal_remembered() {
        use crate::peer_signal::PeerBacking;
        assert_eq!(beacon_backing_reading(PeerBacking::Destroyed), (true, true));
        assert_eq!(
            beacon_backing_reading(PeerBacking::Absent),
            (true, false),
            "an Absent device may still be assembling and hold the newer data"
        );
        assert_eq!(
            beacon_backing_reading(PeerBacking::Unreachable),
            (false, false)
        );
        let none = PeerLifeEvidence::default();
        assert!(reading_proves_serving(&PeerLifeEvidence {
            portal: true,
            ..none
        }));
        assert!(
            !reading_proves_serving(&PeerLifeEvidence {
                liveset: Some(true),
                beacon: true,
                ..none
            }),
            "alive in XHA is not serving"
        );
    }

    #[test]
    fn boot_gate_alerts_once_per_hold_class() {
        use BootGate::*;
        assert_eq!(
            boot_gate_hold_class(HoldPeerAlive),
            boot_gate_hold_class(HoldPeerServedBefore)
        );
        assert_eq!(
            boot_gate_hold_class(HoldPeerAlive),
            boot_gate_hold_class(HoldClearing)
        );
        assert_ne!(
            boot_gate_hold_class(HoldPeerAlive),
            boot_gate_hold_class(HoldPeerBooting)
        );
        assert_ne!(
            boot_gate_hold_class(Proceed),
            boot_gate_hold_class(HoldPeerBooting)
        );
    }

    #[test]
    fn a_remembered_serving_peer_is_void_once_this_nodes_generation_moved() {
        assert!(
            !peer_served_still_applies(Some(Some(1)), Some(2)),
            "resynced or forced since"
        );
        assert!(peer_served_still_applies(Some(Some(2)), Some(2)));
        assert!(
            peer_served_still_applies(Some(Some(2)), None),
            "unreadable now: keep holding"
        );
        assert!(
            peer_served_still_applies(Some(None), Some(2)),
            "recorded without a generation"
        );
        assert!(
            peer_served_still_applies(None, Some(2)),
            "unparseable file: keep holding"
        );
        assert_eq!(parse_peer_served("# x\ncurrent=unknown\n"), Some(None));
        assert_eq!(
            parse_peer_served("current=00000000000000FF\n"),
            Some(Some(0xFF))
        );
        assert_eq!(parse_peer_served("peer seen serving\n"), None);
    }

    #[test]
    fn boot_gate_texts_name_the_reason_of_each_hold() {
        let (s, a) = boot_gate_texts(BootGate::HoldPeerBooting, Duration::from_secs(120));
        assert!(
            s.contains("not serving yet")
                && a.contains("ends after about 11 minutes")
                && a.contains("another 10-minute hold"),
            "{s} / {a}"
        );
        let (s, a) = boot_gate_texts(BootGate::HoldPeerAlive, Duration::from_secs(60));
        assert!(
            s.contains("peer is alive") && a.contains("not serving its own copy"),
            "{s} / {a}"
        );
        let (s, a) = boot_gate_texts(BootGate::HoldClearing, Duration::from_secs(60));
        assert!(
            s.contains("moments ago") && a.contains("100 s"),
            "{s} / {a}"
        );
    }

    #[test]
    fn the_peer_management_address_is_read_from_the_local_pool_database() {
        let db = r#"<database><manifest/><table name="VM"><row ref="OpaqueRef:v" uuid="x" address="9.9.9.9"/></table><table name="host"><row ref="OpaqueRef:a" __ctime="0" uuid="aaaaaaaa-0000-0000-0000-000000000001" name__label="twinstor-1" address="192.0.2.138"/><row ref="OpaqueRef:b" uuid="aaaaaaaa-0000-0000-0000-000000000002" name__label="twinstor-2" address="192.0.2.133"/></table><table name="pool"/></database>"#;
        assert_eq!(
            peer_address_from_state_db(db, "aaaaaaaa-0000-0000-0000-000000000001").as_deref(),
            Some("192.0.2.133")
        );
        assert_eq!(
            peer_address_from_state_db(db, "aaaaaaaa-0000-0000-0000-000000000002").as_deref(),
            Some("192.0.2.138")
        );
        // Not exactly one other host, or no host table: no answer.
        assert_eq!(peer_address_from_state_db(db, "zzz"), None);
        assert_eq!(peer_address_from_state_db("<database/>", "x"), None);
    }

