    #[test]
    fn isolation_decisions_matrix() {
        use IsolationAction::*;
        let now = std::time::Instant::now();
        let old = now - ISOLATED_MASTER_AFTER - Duration::from_secs(1);
        // The connected side fires on the trap signature.
        assert_eq!(
            isolated_master_decision(
                true,
                true,
                true,
                true,
                Some(false),
                Some(old),
                Option::None,
                now
            ),
            Alert
        );
        // Peer claiming slave is the mutual-slave class, not this one.
        assert_eq!(
            isolated_master_decision(
                true,
                true,
                true,
                true,
                Some(true),
                Some(old),
                Option::None,
                now
            ),
            None
        );
        // My own gateway down means I might be the isolated one; not this class.
        assert_eq!(
            isolated_master_decision(
                true,
                true,
                false,
                true,
                Some(false),
                Some(old),
                Option::None,
                now
            ),
            None
        );
        // Peer daemon dead on replication is ordinary node death, HA's job.
        assert_eq!(
            isolated_master_decision(
                true,
                true,
                true,
                false,
                Some(false),
                Some(old),
                Option::None,
                now
            ),
            None
        );
        // Window not matured: hold (probe not even consulted yet).
        assert_eq!(
            isolated_master_decision(
                true,
                true,
                true,
                true,
                Option::None,
                Some(now),
                Option::None,
                now
            ),
            Hold
        );
        // Island side: master, no gateway, peer alive: alert after the window
        // (stand-down disabled here, so it stays alert-only).
        assert_eq!(
            master_isolated_decision(
                true,
                false,
                true,
                true,
                true,
                false,
                Some(1),
                Some(old),
                Option::None,
                now
            ),
            Alert
        );
        assert_eq!(
            master_isolated_decision(
                true,
                true,
                true,
                true,
                true,
                false,
                Some(1),
                Some(old),
                Option::None,
                now
            ),
            None
        );
        assert_eq!(
            master_isolated_decision(
                false,
                false,
                true,
                true,
                true,
                false,
                Some(1),
                Some(old),
                Option::None,
                now
            ),
            None
        );
        assert_eq!(
            master_isolated_decision(
                true,
                false,
                false,
                true,
                true,
                false,
                Some(1),
                Some(old),
                Option::None,
                now
            ),
            None
        );
        // 24h re-alert cadence.
        assert_eq!(
            master_isolated_decision(
                true,
                false,
                true,
                true,
                true,
                false,
                Some(1),
                Some(old),
                Some(now),
                now
            ),
            Hold
        );
        // With stand-down enabled and matured, the peer must be liveset-ready.
        let sd_old = now - ISOLATED_MASTER_STANDDOWN_AFTER - Duration::from_secs(1);
        // Peer is a live liveset member: stand down (isolated-master handoff).
        assert_eq!(
            master_isolated_decision(
                true,
                false,
                true,
                true,
                true,
                true,
                Some(1),
                Some(sd_old),
                Option::None,
                now
            ),
            StandDown
        );
        // Peer alive and UpToDate on replication but not a liveset member
        // (mid-readmission): never stand down into a peer that cannot take the VMs.
        assert_ne!(
            master_isolated_decision(
                true,
                false,
                true,
                true,
                false,
                true,
                Some(1),
                Some(sd_old),
                Option::None,
                now
            ),
            StandDown
        );
        // The wrongful (0-VM) fast path is exempt from liveset-ready (nothing to
        // hand off): it stands down to drop the second writer even when the peer
        // is not a liveset member, so it still works with pool HA off (liveset
        // unreadable).
        let wrong_old = now - WRONGFUL_ISOLATED_MASTER_STANDDOWN_AFTER - Duration::from_secs(1);
        assert_eq!(
            master_isolated_decision(
                true,
                false,
                true,
                true,
                true,
                true,
                Some(0),
                Some(wrong_old),
                Option::None,
                now
            ),
            StandDown
        );
        assert_eq!(
            master_isolated_decision(
                true,
                false,
                true,
                true,
                false,
                true,
                Some(0),
                Some(wrong_old),
                Option::None,
                now
            ),
            StandDown
        );
    }

    #[test]
    fn standdown_rejoin_waits_out_a_gateway_blip() {
        let now = std::time::Instant::now();
        // Never seen back: not ready.
        assert!(!standdown_rejoin_ready(None, now));
        // Back, but not yet stable (a blip): not ready, stays parked.
        let recent = now - STANDDOWN_REJOIN_STABLE + Duration::from_secs(1);
        assert!(!standdown_rejoin_ready(Some(recent), now));
        // Stably back past the window: ready to rejoin.
        let stable = now - STANDDOWN_REJOIN_STABLE - Duration::from_secs(1);
        assert!(standdown_rejoin_ready(Some(stable), now));
    }

    #[test]
    fn master_standdown_only_when_matured_enabled_and_peer_uptodate() {
        use IsolationAction::*;
        let now = std::time::Instant::now();
        // Between the alert window (300 s) and the stand-down window (600 s):
        // alert, never stand down yet even with everything enabled.
        let mid = now - ISOLATED_MASTER_AFTER - Duration::from_secs(1);
        assert_eq!(
            master_isolated_decision(
                true,
                false,
                true,
                true,
                true,
                true,
                Some(1),
                Some(mid),
                Option::None,
                now
            ),
            Alert
        );
        // Past the stand-down window, enabled, peer UpToDate and liveset-ready:
        // stand down.
        let old = now - ISOLATED_MASTER_STANDDOWN_AFTER - Duration::from_secs(1);
        assert_eq!(
            master_isolated_decision(
                true,
                false,
                true,
                true,
                true,
                true,
                Some(1),
                Some(old),
                Some(now),
                now
            ),
            StandDown
        );
        // Data-safety guard: peer not UpToDate, never stand down, keep alerting.
        assert_eq!(
            master_isolated_decision(
                true,
                false,
                true,
                false,
                true,
                true,
                Some(1),
                Some(old),
                Option::None,
                now
            ),
            Alert
        );
        // Feature disabled: never stand down, alert only.
        assert_eq!(
            master_isolated_decision(
                true,
                false,
                true,
                true,
                true,
                false,
                Some(1),
                Some(old),
                Option::None,
                now
            ),
            Alert
        );
        // Not the isolated master (gateway ok, not master, or peer dead): None,
        // whatever the stand-down inputs.
        assert_eq!(
            master_isolated_decision(
                true,
                true,
                true,
                true,
                true,
                true,
                Some(1),
                Some(old),
                Option::None,
                now
            ),
            None
        );
        assert_eq!(
            master_isolated_decision(
                false,
                false,
                true,
                true,
                true,
                true,
                Some(1),
                Some(old),
                Option::None,
                now
            ),
            None
        );
        assert_eq!(
            master_isolated_decision(
                true,
                false,
                false,
                true,
                true,
                true,
                Some(1),
                Some(old),
                Option::None,
                now
            ),
            None
        );
    }

    #[test]
    fn wrongful_isolated_master_fast_standdown() {
        use IsolationAction::*;
        let now = std::time::Instant::now();
        // A wrongful isolated master (0 VMs, arbitrated and enabled, peer
        // UpToDate) stands down after the short debounce, well before the 300 s
        // alert window.
        let fast = now - WRONGFUL_ISOLATED_MASTER_STANDDOWN_AFTER - Duration::from_secs(1);
        assert_eq!(
            master_isolated_decision(
                true,
                false,
                true,
                true,
                true,
                true,
                Some(0),
                Some(fast),
                Option::None,
                now
            ),
            StandDown
        );
        // Debounced: before the short window it holds (a gateway blip must not
        // trigger an instant stand-down).
        let tooearly = now - WRONGFUL_ISOLATED_MASTER_STANDDOWN_AFTER + Duration::from_secs(5);
        assert_eq!(
            master_isolated_decision(
                true,
                false,
                true,
                true,
                true,
                true,
                Some(0),
                Some(tooearly),
                Option::None,
                now
            ),
            Hold
        );
        // Fate-shared (standdown_enabled=false): the fast path never fires, even
        // at 0 VMs past the window; alert only.
        assert_eq!(
            master_isolated_decision(
                true,
                false,
                true,
                true,
                true,
                false,
                Some(0),
                Some(fast),
                Option::None,
                now
            ),
            Hold
        );
        let old = now - ISOLATED_MASTER_STANDDOWN_AFTER - Duration::from_secs(1);
        assert_eq!(
            master_isolated_decision(
                true,
                false,
                true,
                true,
                true,
                false,
                Some(0),
                Some(old),
                Option::None,
                now
            ),
            Alert
        );
        // The data-safety guard still applies: peer not UpToDate, no fast
        // stand-down.
        assert_eq!(
            master_isolated_decision(
                true,
                false,
                true,
                false,
                true,
                true,
                Some(0),
                Some(fast),
                Option::None,
                now
            ),
            Hold
        );
        // A serving master (VMs > 0) does not take the fast path: at the short
        // window it still holds or alerts and only stands down at the full 600 s
        // window.
        assert_eq!(
            master_isolated_decision(
                true,
                false,
                true,
                true,
                true,
                true,
                Some(2),
                Some(fast),
                Option::None,
                now
            ),
            Hold
        );
        assert_eq!(
            master_isolated_decision(
                true,
                false,
                true,
                true,
                true,
                true,
                Some(2),
                Some(old),
                Some(now),
                now
            ),
            StandDown
        );
        // An unknown VM count (None) counts as "has VMs": never the fast path.
        assert_eq!(
            master_isolated_decision(
                true,
                false,
                true,
                true,
                true,
                true,
                Option::None,
                Some(fast),
                Option::None,
                now
            ),
            Hold
        );
    }

    #[test]
    fn whole_switch_decision_matrix() {
        use crate::peer_signal::PeerGateway::{Down, Unreachable, Up};
        use WholeSwitchAction::*;
        let now = std::time::Instant::now();
        let confirm = Duration::from_secs(15);
        let old = now - Duration::from_secs(20); // condition held past confirm
        let recent = now - Duration::from_secs(5); // not yet confirmed
        // Fate-shared: never acts (no direct link to learn the peer's gateway).
        assert_eq!(
            whole_switch_decision(false, false, Down, Some(old), false, now, confirm),
            None
        );
        // Gateway up, not held: nothing.
        assert_eq!(
            whole_switch_decision(true, true, Up, Option::None, false, now, confirm),
            None
        );
        // Gateway up while holding: release and re-arm.
        assert_eq!(
            whole_switch_decision(true, true, Up, Some(old), true, now, confirm),
            Release
        );
        // Isolated, peer gateway up: single-host isolation, not our case.
        assert_eq!(
            whole_switch_decision(true, false, Up, Some(old), false, now, confirm),
            None
        );
        // Isolated, peer unreachable on the direct link: real death, not our case.
        assert_eq!(
            whole_switch_decision(true, false, Unreachable, Some(old), false, now, confirm),
            None
        );
        // Isolated, peer gateway down but not yet sustained: confirming.
        assert_eq!(
            whole_switch_decision(true, false, Down, Some(recent), false, now, confirm),
            Confirming
        );
        // Isolated, peer gateway down, confirmed: hold (ha-disable, keep VMs).
        assert_eq!(
            whole_switch_decision(true, false, Down, Some(old), false, now, confirm),
            Hold
        );
        // Already holding while still isolated: keep holding (no repeat action).
        assert_eq!(
            whole_switch_decision(true, false, Down, Some(old), true, now, confirm),
            None
        );
        // A single-tick blip (since just opened) never fires the hold.
        assert_eq!(
            whole_switch_decision(true, false, Down, Some(now), false, now, confirm),
            Confirming
        );
        // Asymmetric recovery: holding, still isolated, but the peer's gateway
        // came back (peer Up), so this is now single-host isolation. Release so
        // failover can run; otherwise our VMs stay stranded until our gateway
        // returns.
        assert_eq!(
            whole_switch_decision(true, false, Up, Some(old), true, now, confirm),
            Release
        );
        // Holding, still isolated, but the peer went unreachable (real death, or
        // the direct link dropped too): release so the failover path takes over.
        assert_eq!(
            whole_switch_decision(true, false, Unreachable, Some(old), true, now, confirm),
            Release
        );
    }

    #[test]
    fn whole_switch_probe_miss_tolerance() {
        use crate::peer_signal::PeerGateway::{Down, Unreachable, Up};
        let tol = 3;
        // A transient Unreachable during a whole-switch outage is held as Down,
        // counting up.
        assert_eq!(
            whole_switch_smooth_peer_gw(Unreachable, true, 0, tol),
            (Down, 1)
        );
        assert_eq!(
            whole_switch_smooth_peer_gw(Unreachable, true, 2, tol),
            (Down, 3)
        );
        // Sustained past tolerance: pass the real Unreachable through (real death).
        assert_eq!(
            whole_switch_smooth_peer_gw(Unreachable, true, 3, tol),
            (Unreachable, 3)
        );
        // A definitive Down read resets the miss budget.
        assert_eq!(whole_switch_smooth_peer_gw(Down, true, 2, tol), (Down, 0));
        // A definitive Up (peer gateway really back) passes through and resets.
        assert_eq!(whole_switch_smooth_peer_gw(Up, true, 2, tol), (Up, 0));
        // Not in a whole-switch outage: no smoothing, Unreachable passes through.
        assert_eq!(
            whole_switch_smooth_peer_gw(Unreachable, false, 0, tol),
            (Unreachable, 0)
        );
        // a booting peer's Unknown is never smoothed to Down, even during a
        // whole-switch outage, and resets the miss budget. This stops a rebooting
        // peer (which serves Unknown until its gateway is confirmed) from being
        // read as a whole-switch outage and triggering the keep-VMs disarm
        // (dual-run risk).
        use crate::peer_signal::PeerGateway::Unknown;
        assert_eq!(
            whole_switch_smooth_peer_gw(Unknown, true, 2, tol),
            (Unknown, 0)
        );
        assert_eq!(
            whole_switch_smooth_peer_gw(Unknown, false, 0, tol),
            (Unknown, 0)
        );
    }

    #[test]
    fn whole_switch_guard_decision_matrix() {
        use GuardAction::*;
        let now = std::time::Instant::now();
        let confirm = Duration::from_secs(15);
        let fresh = Duration::from_secs(30);
        let matured = now - Duration::from_secs(20); // clock past confirm
        let recent = now - Duration::from_secs(5); // clock not yet at confirm
        let dn_fresh = Some(now - Duration::from_secs(4)); // reachable Down seen recently
        let dn_stale = Some(now - Duration::from_secs(45)); // last reachable Down aged out
        // args: arbitrated, gateway_ok, peer_up_now, gw_down_since, peer_down_since,
        //       last_reachable_down, already_disarmed, now, confirm, freshness
        let d = |arb, gw, up, gwds, pds, lrd, dis| {
            whole_switch_guard_decision(arb, gw, up, gwds, pds, lrd, dis, now, confirm, fresh)
        };

        // Fate-shared: never acts.
        assert_eq!(
            d(
                false,
                false,
                false,
                Some(matured),
                Some(matured),
                dn_fresh,
                false
            ),
            None
        );
        // Both clocks matured and a fresh reachable peer Down: disarm (real
        // whole-switch outage).
        assert_eq!(
            d(
                true,
                false,
                false,
                Some(matured),
                Some(matured),
                dn_fresh,
                false
            ),
            Disarm
        );
        // Peer never confirmed Down (a single-host peer serves Up; for a booting
        // peer's Unknown the caller keeps peer_down_since None): never disarm.
        assert_eq!(
            d(
                true,
                false,
                false,
                Some(matured),
                Option::None,
                Option::None,
                false
            ),
            None
        );
        // Peer's Down not yet matured (a brief blip): do not disarm.
        assert_eq!(
            d(
                true,
                false,
                false,
                Some(matured),
                Some(recent),
                dn_fresh,
                false
            ),
            None
        );
        // My gateway-down not yet matured: confirming.
        assert_eq!(
            d(
                true,
                false,
                false,
                Some(recent),
                Some(matured),
                dn_fresh,
                false
            ),
            None
        );
        // Congestion tolerance: peer_down_since matured and was kept across a run
        // of Unreachable, but the last reachable Down is stale (the peer went away,
        // or timeouts for longer than the freshness window): do not disarm on a
        // peer we can no longer confirm present.
        assert_eq!(
            d(
                true,
                false,
                false,
                Some(matured),
                Some(matured),
                dn_stale,
                false
            ),
            None
        );
        // Already disarmed, still isolated, peer recently confirmed still down:
        // hold.
        assert_eq!(
            d(
                true,
                false,
                false,
                Some(matured),
                Some(matured),
                dn_fresh,
                true
            ),
            None
        );
        // Already disarmed, our gateway back: release.
        assert_eq!(
            d(
                true,
                true,
                false,
                Option::None,
                Option::None,
                dn_fresh,
                true
            ),
            Rearm
        );
        // Already disarmed, gateway still down but the peer now serves Up
        // (asymmetric recovery): release to the main tick's stand-down.
        assert_eq!(
            d(
                true,
                false,
                true,
                Some(matured),
                Option::None,
                dn_fresh,
                true
            ),
            Rearm
        );
        // Release on stale: already disarmed, peer neither Up nor gateway back,
        // but we can no longer confirm it still down: release (stand-down is
        // data-safe, and this caps an asymmetric-recovery dual-run to the
        // freshness window).
        assert_eq!(
            d(
                true,
                false,
                false,
                Some(matured),
                Some(matured),
                dn_stale,
                true
            ),
            Rearm
        );
        // Not disarmed, gateway up: nothing.
        assert_eq!(
            d(
                true,
                true,
                false,
                Option::None,
                Option::None,
                dn_fresh,
                false
            ),
            None
        );
    }

    #[test]
    fn isolated_slave_standdown_decision_matrix() {
        // args: (standdown_enabled, self_slave, gateway_ok, peer_gateway_up,
        //        peer_uptodate, has_vms, since, now, after)
        let now = std::time::Instant::now();
        let after = Duration::from_secs(120);
        let old = now - Duration::from_secs(150); // held past `after`
        let recent = now - Duration::from_secs(30); // not yet stable
        // Single-host slave isolation, all signals present and stable: stand down.
        assert!(isolated_slave_standdown_decision(
            true,
            true,
            false,
            true,
            true,
            true,
            Some(old),
            now,
            after
        ));
        // Not yet stable: no.
        assert!(!isolated_slave_standdown_decision(
            true,
            true,
            false,
            true,
            true,
            true,
            Some(recent),
            now,
            after
        ));
        // First sample opens the clock: no.
        assert!(!isolated_slave_standdown_decision(
            true,
            true,
            false,
            true,
            true,
            true,
            Some(now),
            now,
            after
        ));
        // Each guard blocks it:
        assert!(!isolated_slave_standdown_decision(
            false,
            true,
            false,
            true,
            true,
            true,
            Some(old),
            now,
            after
        )); // stand-down disabled
        assert!(!isolated_slave_standdown_decision(
            true,
            false,
            false,
            true,
            true,
            true,
            Some(old),
            now,
            after
        )); // I am master, not slave
        assert!(!isolated_slave_standdown_decision(
            true,
            true,
            true,
            true,
            true,
            true,
            Some(old),
            now,
            after
        )); // my gateway up: not isolated
        // Master gateway down over the direct link means a whole-switch outage:
        // never here (that is the whole-switch hold's job).
        assert!(!isolated_slave_standdown_decision(
            true,
            true,
            false,
            false,
            true,
            true,
            Some(old),
            now,
            after
        ));
        assert!(!isolated_slave_standdown_decision(
            true,
            true,
            false,
            true,
            false,
            true,
            Some(old),
            now,
            after
        )); // peer not UpToDate: unsafe hand-off
        assert!(!isolated_slave_standdown_decision(
            true,
            true,
            false,
            true,
            true,
            false,
            Some(old),
            now,
            after
        )); // no VMs to hand off
    }

    #[test]
    fn slave_fence_ha_disable_only_after_a_reboot() {
        let boot_a = "11111111-1111-1111-1111-111111111111";
        let boot_b = "22222222-2222-2222-2222-222222222222";
        let slave_marker = format!(
            "isolated-slave fence-to-failover; parked until the client network returns\nboot_id={boot_a}\n"
        );
        // Same boot means pre-fence ticks: let the armed xhad self-fence, do not
        // ha-disable.
        assert!(!slave_fence_needs_ha_disable(&slave_marker, boot_a));
        // Different boot means the fence happened (we rebooted): ha-disable to
        // avoid a loop.
        assert!(slave_fence_needs_ha_disable(&slave_marker, boot_b));
        // The master-path marker carries no boot_id line: never ha-disable via
        // this path.
        let master_marker =
            "isolated-master storage stand-down; parked until the client network returns\n";
        assert!(!slave_fence_needs_ha_disable(master_marker, boot_a));
        assert!(!slave_fence_needs_ha_disable(master_marker, boot_b));
        // Empty/unreadable current boot_id must not spuriously match an empty stamp.
        assert!(!slave_fence_needs_ha_disable(
            "isolated-slave fence-to-failover;\nboot_id=\n",
            boot_a
        ));
        // An unreadable current boot_id (proc read failed) must not ha-disable: we
        // cannot prove a reboot, so preserve the intended self-fence rather than
        // pre-empt it and strand the VMs.
        assert!(!slave_fence_needs_ha_disable(&slave_marker, ""));
    }

    #[test]
    fn yield_hold_alerts_only_on_the_exact_signature() {
        use YieldHoldAction::*;
        let now = std::time::Instant::now();
        let old = now - YIELD_HOLD_ALERT_AFTER - Duration::from_secs(1);
        // The signature: yielded, disconnected, gateway fine, peer absent.
        assert_eq!(
            yield_hold_decision(true, false, true, false, Some(old), Option::None, now),
            Alert
        );
        // Peer reachable: the pair heals itself, no alert.
        assert_eq!(
            yield_hold_decision(true, false, true, true, Some(old), Option::None, now),
            None
        );
        // Gateway down: the yield is still justified, no alert.
        assert_eq!(
            yield_hold_decision(true, false, false, false, Some(old), Option::None, now),
            None
        );
        // Connected or not yielded: nothing to watch.
        assert_eq!(
            yield_hold_decision(true, true, true, false, Some(old), Option::None, now),
            None
        );
        assert_eq!(
            yield_hold_decision(false, false, true, false, Some(old), Option::None, now),
            None
        );
        // Window not matured: hold.
        assert_eq!(
            yield_hold_decision(true, false, true, false, Some(now), Option::None, now),
            Hold
        );
        // Re-alert only after the 24h cadence.
        assert_eq!(
            yield_hold_decision(true, false, true, false, Some(old), Some(now), now),
            Hold
        );
        let stale = now - DEGRADED_REALERT_AFTER - Duration::from_secs(1);
        assert_eq!(
            yield_hold_decision(true, false, true, false, Some(old), Some(stale), now),
            Alert
        );
    }

    #[test]
    fn mutual_slave_needs_proof_and_tiebreak() {
        use MasterlessAction::*;
        let now = std::time::Instant::now();
        let alert_age = now - MASTERLESS_ALERT_AFTER - Duration::from_secs(1);
        let recover_age = now - MASTERLESS_RECOVER_AFTER - Duration::from_secs(1);
        // Unproven peer state: never alerts as this class.
        assert_eq!(
            mutual_slave_decision(
                true,
                true,
                Some(false),
                true,
                true,
                Some(alert_age),
                false,
                Option::None,
                now
            ),
            Hold
        );
        assert_eq!(
            mutual_slave_decision(
                true,
                true,
                Option::None,
                true,
                true,
                Some(alert_age),
                false,
                Option::None,
                now
            ),
            Hold
        );
        // Proven mutual-slave: alert.
        assert_eq!(
            mutual_slave_decision(
                true,
                true,
                Some(true),
                true,
                true,
                Some(alert_age),
                false,
                Option::None,
                now
            ),
            Alert
        );
        // Recovery: lower hostname only, storage Connected, past the window.
        assert_eq!(
            mutual_slave_decision(
                true,
                true,
                Some(true),
                true,
                true,
                Some(recover_age),
                true,
                Option::None,
                now
            ),
            Recover
        );
        assert_eq!(
            mutual_slave_decision(
                true,
                true,
                Some(true),
                false,
                true,
                Some(recover_age),
                true,
                Option::None,
                now
            ),
            Hold
        );
        assert_eq!(
            mutual_slave_decision(
                true,
                true,
                Some(true),
                true,
                false,
                Some(recover_age),
                true,
                Option::None,
                now
            ),
            Hold
        );
        // Cooldown shared with the slave-of-self recovery.
        let recent = now - Duration::from_secs(60);
        assert_eq!(
            mutual_slave_decision(
                true,
                true,
                Some(true),
                true,
                true,
                Some(recover_age),
                true,
                Some(recent),
                now
            ),
            Hold
        );
        // xe alive or not following the peer: not this class.
        assert_eq!(
            mutual_slave_decision(
                true,
                false,
                Some(true),
                true,
                true,
                Some(recover_age),
                true,
                Option::None,
                now
            ),
            None
        );
        assert_eq!(
            mutual_slave_decision(
                false,
                true,
                Some(true),
                true,
                true,
                Some(recover_age),
                true,
                Option::None,
                now
            ),
            None
        );
    }

    #[test]
    fn halt_provenance_attribution_matrix() {
        // Unhealthy pool now: orphan regardless of history.
        assert!(halt_is_incident_orphan(false, Some(true), false, false));
        // Open heal episode: orphan even if storage already looks healthy.
        assert!(halt_is_incident_orphan(true, Some(true), true, false));
        // Previous scan unhealthy (halt bracketed by the incident): orphan.
        assert!(halt_is_incident_orphan(true, Some(false), false, false));
        // Healthy now, healthy before, no episode: operator-shaped.
        assert!(!halt_is_incident_orphan(true, Some(true), false, false));
        // Daemon restart into a fully healthy pool: unknown provenance, so
        // conservative (alert only).
        assert!(!halt_is_incident_orphan(true, None, false, false));
        // Daemon restart mid-incident (post-fence boot): orphan.
        assert!(halt_is_incident_orphan(false, None, false, false));
        // xe outage between scans (toolstack restart, zombie xapi): the gap
        // itself is incident evidence, so orphan even with healthy brackets.
        assert!(halt_is_incident_orphan(true, Some(true), false, true));
    }

    #[test]
    fn halt_attribution_reads_storage_only() {
        // Converged storage is "healthy" for attribution whatever pool HA
        // says: a VM halted while HA was off is operator-shaped.
        assert!(halt_attribution_healthy(Some(&online_with_peer())));
        assert!(!halt_attribution_healthy(Some(&connecting_secondary())));
        assert!(!halt_attribution_healthy(Some(&DrbdStatus {
            peer_disk: Some(DiskState::Inconsistent),
            ..online_with_peer()
        })));
        // Unreadable DRBD status never reads as healthy.
        assert!(!halt_attribution_healthy(None));
        // VMs halted before HA was turned on, first seen (daemon start, or
        // right after an HA-off sample) on converged storage with no episode:
        // not orphans, never auto-started.
        let healthy = halt_attribution_healthy(Some(&online_with_peer()));
        assert!(!halt_is_incident_orphan(healthy, None, false, false));
        assert!(!halt_is_incident_orphan(
            healthy,
            Some(healthy),
            false,
            false
        ));
    }

    #[test]
    fn stale_serving_primary_demote_needs_signature_growth() {
        let mut st = connecting_secondary();
        st.connection = crate::drbd::ConnectionState::StandAlone;
        st.role = Role::Primary;
        st.suspended_user = false;
        // All conditions met and a refusal newer than the episode's first
        // (kernel stamps).
        assert!(should_demote_stale_serving_primary(
            &st,
            3,
            Some(500.25),
            731.5
        ));
        // The same newest refusal: from before the episode, never fire.
        assert!(!should_demote_stale_serving_primary(
            &st,
            3,
            Some(500.25),
            500.25
        ));
        // No baseline captured: never fire.
        assert!(!should_demote_stale_serving_primary(&st, 3, None, 731.5));
        // Below the abort threshold: never fire.
        assert!(!should_demote_stale_serving_primary(
            &st,
            2,
            Some(500.25),
            731.5
        ));
        // The suspended flavour is the other path's job.
        st.suspended_user = true;
        assert!(!should_demote_stale_serving_primary(
            &st,
            3,
            Some(500.25),
            731.5
        ));
        // Not Primary: nothing to demote.
        st.suspended_user = false;
        st.role = Role::Secondary;
        assert!(!should_demote_stale_serving_primary(
            &st,
            3,
            Some(500.25),
            731.5
        ));
    }

    #[test]
    fn the_newest_refusal_is_read_from_the_kernel_log_own_clock() {
        let r = "twinstor-data";
        let a = "[  559.007950] drbd twinstor-data/0 drbd0 x: I shall become SyncTarget, but I am primary!";
        let b = "[21687.655636] drbd twinstor-data/0 drbd0 x: I shall become SyncTarget, but I am primary!";
        let other = "[21690.000000] drbd twinstor-other/0 drbd1 x: I shall become SyncTarget, but I am primary!";
        assert_eq!(newest_refusal_stamp("", r), None);
        assert_eq!(newest_refusal_stamp(a, r), Some(559.00795));
        // The newest one for this resource, wherever the log starts (a boot
        // with no link ever Connected, or a rotated buffer).
        assert_eq!(
            newest_refusal_stamp(&[a, b, other].join("\n"), r),
            Some(21687.655636)
        );
        assert_eq!(
            newest_refusal_stamp(
                "[Wed Oct 21 10:07:02 2026] drbd twinstor-data/0 drbd0 x: I shall become SyncTarget, but I am primary!",
                r
            ),
            None,
            "human stamps (-T) are not used"
        );
    }

    #[tokio::test]
    async fn dance_gate_refusal_is_cost_free() {
        // A pre-flight gate refusal (storage not settled) must come back as
        // NotAttempted (no episode opened, no DRBD action taken), so the caller
        // neither burns a strike nor resets the stability clock.
        let drbd = std::sync::Arc::new(MockDrbd::new(connecting_secondary()));
        let (mut sm, _) = StateMachine::new(
            test_config(),
            Box::new(ArcDrbd(drbd.clone())),
            Box::new(MockIscsi::new()),
        );
        let marker = std::env::temp_dir().join("twinstor-test-dance-refusal-episode");
        sm.episode_path = marker.to_string_lossy().to_string();
        let _ = std::fs::remove_file(&marker);

        let outcome = sm.run_failback_dance(&["10.0.0.2".to_string()]).await;
        assert!(
            matches!(outcome, DanceOutcome::NotAttempted(_)),
            "gate refusal must be NotAttempted, got {outcome:?}"
        );
        assert!(!marker.exists(), "a refused dance must not open an episode");
        assert!(
            !drbd.calls().iter().any(|c| *c != "status"),
            "a refused dance must not touch DRBD beyond reading status: {:?}",
            drbd.calls()
        );
    }

    #[tokio::test]
    async fn failback_restore_relogs_the_loopback_only_when_the_target_is_back() {
        // Every dance exit (success and the two aborts) goes through
        // restore_serving: once the target is back up it must ask for the
        // loopback re-login, because the dance's own reconnect never produces
        // the connect edge that would re-plug it.
        let (mut sm, _) = StateMachine::new(
            test_config(),
            Box::new(ArcDrbd(std::sync::Arc::new(MockDrbd::new(
                connecting_secondary(),
            )))),
            Box::new(MockIscsi::new()),
        );
        sm.restore_serving().await;
        assert_eq!(sm.loopback_relogin_requests, 1);
        // Target restart failed: nothing to log in to; the Online tick retries.
        let (mut sm, _) = StateMachine::new(
            test_config(),
            Box::new(ArcDrbd(std::sync::Arc::new(MockDrbd::new(
                connecting_secondary(),
            )))),
            Box::new(FailingIscsi),
        );
        sm.restore_serving().await;
        assert_eq!(sm.loopback_relogin_requests, 0);
    }

    #[tokio::test(start_paused = true)]
    async fn loopback_relogin_is_bounded_and_skipped_when_present() {
        use std::sync::atomic::AtomicU32;
        let run = |present_after: Option<u32>| async move {
            let logins = std::sync::Arc::new(AtomicU32::new(0));
            let l = logins.clone();
            let ok = relogin_until_present(
                LOOPBACK_RELOGIN_ATTEMPTS,
                LOOPBACK_RELOGIN_GAP,
                || {
                    let n = l.load(Ordering::Relaxed);
                    async move { present_after.is_some_and(|k| n >= k) }
                },
                || {
                    logins.fetch_add(1, Ordering::Relaxed);
                    async {}
                },
            )
            .await;
            (ok, logins.load(Ordering::Relaxed))
        };
        // Already logged in: no login at all.
        assert_eq!(run(Some(0)).await, (true, 0));
        // Absent, comes up after the first login.
        assert_eq!(run(Some(1)).await, (true, 1));
        // Never comes up: the bounded number of logins, then give up.
        assert_eq!(run(None).await, (false, LOOPBACK_RELOGIN_ATTEMPTS));
    }

    #[tokio::test]
    async fn episode_marker_persists_and_orphan_closes_on_restart() {
        let (mut sm, _) = StateMachine::new(
            test_config(),
            Box::new(ArcDrbd(std::sync::Arc::new(MockDrbd::new(
                connecting_secondary(),
            )))),
            Box::new(MockIscsi::new()),
        );
        let marker = std::env::temp_dir().join("twinstor-test-open-episode");
        sm.episode_path = marker.to_string_lossy().to_string();
        let _ = std::fs::remove_file(&marker);

        sm.episode_open("splitbrain");
        assert!(marker.exists(), "open must persist the episode id");
        assert!(
            std::fs::read_to_string(&marker)
                .unwrap()
                .starts_with("splitbrain-")
        );
        sm.episode_close("converged-or-reset");
        assert!(!marker.exists(), "close must remove the marker");

        // A marker left behind by a dead daemon is closed on recovery.
        std::fs::write(&marker, "splitbrain-12345").unwrap();
        sm.episode_recover_orphan();
        assert!(!marker.exists(), "orphan recovery must consume the marker");
        assert!(sm.episode.is_none());
    }

    #[test]
    fn operator_discard_is_done_only_once_the_resync_from_the_peer_runs() {
        use crate::drbd::Replication;
        let mut s = connecting_secondary();
        assert_eq!(operator_discard_gate(&s), OperatorDiscard::Hold);
        s.connection = ConnectionState::StandAlone;
        assert_eq!(operator_discard_gate(&s), OperatorDiscard::ReArm);
        s.connection = ConnectionState::Connected;
        s.disk = DiskState::Outdated;
        s.peer_disk = Some(DiskState::UpToDate);
        assert_eq!(
            operator_discard_gate(&s),
            OperatorDiscard::Hold,
            "connected but no resync yet"
        );
        s.replication = Some(Replication::SyncTarget);
        assert_eq!(operator_discard_gate(&s), OperatorDiscard::Done);
        s.replication = None;
        s.disk = DiskState::UpToDate;
        assert_eq!(
            operator_discard_gate(&s),
            OperatorDiscard::Done,
            "already resynced"
        );
    }

    #[tokio::test]
    async fn a_pending_operator_discard_keeps_the_node_down_and_rearms_the_offer() {
        // The operator discarded this copy; the daemon restarts before the
        // peer took the offer. It must never promote or export the copy.
        let mut status = connecting_secondary();
        status.connection = ConnectionState::StandAlone;
        let drbd = std::sync::Arc::new(MockDrbd::new(status));
        let (mut sm, _) = StateMachine::new(
            test_config(),
            Box::new(ArcDrbd(drbd.clone())),
            Box::new(MockIscsi::new()),
        );
        std::fs::write(&sm.discard_request_path, "requested").unwrap();
        for _ in 0..3 {
            assert!(!sm.try_go_online().await.unwrap());
        }
        assert!(
            !drbd.primary_called.load(Ordering::Relaxed),
            "a discarded copy is never promoted"
        );
        assert_eq!(
            drbd.calls()
                .iter()
                .filter(|c| **c == "connect_discard")
                .count(),
            1,
            "the offer is re-armed, paced: {:?}",
            drbd.calls()
        );
        assert_eq!(sm.state(), NodeState::Init);
        // The peer takes it: Connected as SyncTarget ends the request.
        let mut st = connecting_secondary();
        st.connection = ConnectionState::Connected;
        st.disk = DiskState::Inconsistent;
        st.peer_disk = Some(DiskState::UpToDate);
        st.replication = Some(crate::drbd::Replication::SyncTarget);
        drbd.set_status(st);
        let _ = sm.try_go_online().await;
        assert!(!std::path::Path::new(&sm.discard_request_path).exists());
    }

    #[tokio::test]
    async fn connecting_node_defers_promote_instead_of_splitting() {
        // A node that boots while DRBD is still Connecting must not
        // force-promote alone (that causes a split-brain on a staggered double
        // reboot). The first try_go_online tick spawns the background
        // wait-connect and defers: no promote, still Init.
        let config = test_config();
        let drbd = std::sync::Arc::new(MockDrbd::new(connecting_secondary()));
        let (mut sm, _) = StateMachine::new(
            config.clone(),
            Box::new(ArcDrbd(drbd.clone())),
            Box::new(MockIscsi::new()),
        );

        let deferred = sm.try_go_online().await.unwrap();
        assert!(
            !deferred,
            "Connecting node must defer (Ok(false)), not go Online"
        );
        assert!(
            !drbd.primary_called.load(Ordering::Relaxed),
            "must not promote to Primary while DRBD is still Connecting"
        );
        assert_eq!(sm.state(), NodeState::Init);
    }

    #[tokio::test]
    async fn init_promotes_and_starts_iscsi() {
        let config = test_config();
        let drbd = std::sync::Arc::new(MockDrbd::new(starting_secondary()));

        let (mut sm, _) = StateMachine::new(
            config.clone(),
            Box::new(ArcDrbd(drbd.clone())),
            Box::new(MockIscsi::new()),
        );
        // Arbitrated: the direct-link statefile discriminator is trustworthy, so
        // a lone-survivor boot promotes and serves immediately (the fate-shared
        // hold is tested separately below).
        sm.arbitrated = true;

        let (shutdown_tx, shutdown_rx) = tokio::sync::broadcast::channel(1);
        let sm_handle = tokio::spawn(async move {
            sm.run(shutdown_rx).await.unwrap();
            sm.state()
        });

        tokio::time::sleep(Duration::from_millis(50)).await;
        let _ = shutdown_tx.send(());
        let state = sm_handle.await.unwrap();

        assert_eq!(state, NodeState::Online);
        assert!(drbd.primary_called.load(Ordering::Relaxed));
    }

    #[tokio::test]
    async fn fateshared_lone_survivor_holds_instead_of_serving() {
        // In fate-shared mode a lone-survivor boot (peer gone, StandAlone and
        // UpToDate, no split-brain marker) must not promote and serve at once:
        // the peer may be isolated but alive, and serving would let XHA
        // self-promote against it (VM double-run). It holds in Init for the
        // serve grace (init_promotes_and_starts_iscsi covers arbitrated).
        let config = test_config();
        let drbd = std::sync::Arc::new(MockDrbd::new(starting_secondary()));
        let (mut sm, _) = StateMachine::new(
            config.clone(),
            Box::new(ArcDrbd(drbd.clone())),
            Box::new(MockIscsi::new()),
        );
        sm.arbitrated = false; // fate-shared: discriminator unreliable

        let (shutdown_tx, shutdown_rx) = tokio::sync::broadcast::channel(1);
        let sm_handle = tokio::spawn(async move {
            sm.run(shutdown_rx).await.unwrap();
            sm.state()
        });

        tokio::time::sleep(Duration::from_millis(50)).await;
        let _ = shutdown_tx.send(());
        let state = sm_handle.await.unwrap();

        assert_eq!(
            state,
            NodeState::Init,
            "fate-shared lone survivor must hold, not serve"
        );
        assert!(
            !drbd.primary_called.load(Ordering::Relaxed),
            "must not promote during the fate-shared serve hold"
        );
    }

    #[test]
    fn an_undelivered_hold_alert_is_retried_quietly_with_backoff() {
        // While isolated, a failed alert delivery must not re-log the hold
        // warning every tick: failures back off 30 s, 60 s, ... up to 10 min,
        // and a delivery resets the pacing.
        let t0 = std::time::Instant::now();
        let mut r = AlertRetry::default();
        assert!(r.due(t0), "the first attempt is immediate");
        r.failed(t0);
        assert!(!r.due(t0 + Duration::from_secs(29)));
        assert!(r.due(t0 + Duration::from_secs(30)));
        let mut t = t0 + Duration::from_secs(30);
        let mut waits = Vec::new();
        for _ in 0..6 {
            r.failed(t);
            waits.push(r.backoff.as_secs());
            t += r.backoff;
        }
        assert_eq!(
            waits,
            [60, 120, 240, 480, 600, 600],
            "doubling, capped at ALERT_RETRY_MAX"
        );
        r.reset();
        assert_eq!(r, AlertRetry::default());
        assert!(r.due(t));
    }

    #[test]
    fn lone_survivor_never_promotes_while_isolated() {
        use LoneSurvivorAction::*;
        let g = FATESHARED_CONFIRMED_DEAD_HOLD;
        let young = Duration::from_secs(30);
        let expired = g + Duration::from_secs(1);
        // Inside the grace the gateway does not matter: hold.
        assert_eq!(lone_survivor_decision(young, g, Some(true)), Hold);
        assert_eq!(lone_survivor_decision(young, g, Some(false)), Hold);
        // Grace expired, local network healthy (the gateway or a ping target
        // answers): the peer is presumed dead.
        assert_eq!(lone_survivor_decision(expired, g, Some(true)), Promote);
        assert_eq!(lone_survivor_decision(g, g, Some(true)), Promote);
        // Grace expired but nothing in the probe set answers: we are the
        // isolated side and must never promote, however long the hold has run
        // (38 h below).
        assert_eq!(
            lone_survivor_decision(expired, g, Some(false)),
            HoldIsolated
        );
        assert_eq!(
            lone_survivor_decision(Duration::from_secs(38 * 3600), g, Some(false)),
            HoldIsolated
        );
        // No tiebreaker configured at all (deployed without one): the fence
        // handler refuses a lone promote with an empty probe set, so the node
        // holds for an operator instead of attempting a promote that leaves a
        // suspend and a yield marker behind.
        assert_eq!(lone_survivor_decision(expired, g, None), HoldNoTiebreaker);
        assert_eq!(lone_survivor_decision(young, g, None), Hold);
    }

