    // -- DRBD self-heal (leftover suspend, mutual-SyncSource) ---------------

    #[test]
    fn resume_io_only_when_suspended_and_fully_healthy() {
        // Lift the leftover suspend only when it is the user/script kind and the
        // cluster is provably healthy again.
        assert!(should_resume_io(&suspended_but_healthy()));
        // A fence-peer decision's freeze is held too: `resume-io` would release it.
        assert!(!should_resume_io(&DrbdStatus {
            suspended_fencing: true,
            ..suspended_but_healthy()
        }));
        // Not suspended: nothing to do.
        assert!(!should_resume_io(&online_with_peer()));
        // Suspended but the peer is not UpToDate (still converging): hold off,
        // resuming I/O before redundancy is restored would serve unprotected.
        let mut s = suspended_but_healthy();
        s.peer_disk = Some(DiskState::Inconsistent);
        assert!(!should_resume_io(&s));
        // Suspended but disconnected: the StandAlone/split-brain paths own this.
        let mut s = suspended_but_healthy();
        s.connection = ConnectionState::StandAlone;
        assert!(!should_resume_io(&s));
    }

    #[test]
    fn mutual_sync_source_signature() {
        assert!(looks_like_mutual_sync_source(&mutual_sync_source()));
        // A legitimate resync target (local Inconsistent, SyncTarget) is not it.
        assert!(!looks_like_mutual_sync_source(&syncing_from_peer()));
        // Healthy Established (no replication line) is not it.
        assert!(!looks_like_mutual_sync_source(&online_with_peer()));
        // Same shape but peer already UpToDate (resync finishing) is not it.
        let mut s = mutual_sync_source();
        s.peer_disk = Some(DiskState::UpToDate);
        assert!(!looks_like_mutual_sync_source(&s));
    }

    #[test]
    fn mutual_sync_decision_clears_when_not_limbo() {
        // A signature break ends the episode: all tracking (including the
        // ever-advanced disqualification) resets, so a resumed resync gets a
        // fresh full window.
        let now = std::time::Instant::now();
        let (done, started, advanced, recover) = mutual_sync_decision(
            &online_with_peer(),
            Some(0.0),
            Some(now),
            true,
            now,
            RESYNC_STUCK_RECOVER_AFTER,
            true,
        );
        assert_eq!(done, None);
        assert_eq!(started, None);
        assert!(!advanced);
        assert!(!recover);
    }

    #[test]
    fn mutual_sync_decision_first_sample_starts_episode() {
        // The first limbo sample stamps the episode start; no verdict yet.
        let now = std::time::Instant::now();
        let (done, started, advanced, recover) = mutual_sync_decision(
            &mutual_sync_source(),
            None,
            None,
            false,
            now,
            RESYNC_STUCK_RECOVER_AFTER,
            true,
        );
        assert_eq!(done, Some(0.0));
        assert_eq!(started, Some(now));
        assert!(!advanced);
        assert!(!recover);
    }

    #[test]
    fn mutual_sync_decision_progress_permanently_disqualifies_episode() {
        // `done` advanced from 1.0 to 2.0: a real resync. The episode is
        // disqualified for good: even a later stall past the window must never
        // recover while the signature holds.
        let now = std::time::Instant::now();
        let old = now - Duration::from_secs(3600);
        let mut s = mutual_sync_source();
        s.resync_done = Some(2.0);
        let (done, started, advanced, recover) = mutual_sync_decision(
            &s,
            Some(1.0),
            Some(old),
            false,
            now,
            RESYNC_STUCK_RECOVER_AFTER,
            true,
        );
        assert_eq!(done, Some(2.0));
        assert_eq!(started, Some(old), "episode start survives progress");
        assert!(advanced);
        assert!(!recover);

        // The stall that follows, however long, stays disqualified.
        let later = now + Duration::from_secs(7200);
        let (_, _, still_advanced, recover) = mutual_sync_decision(
            &s,
            Some(2.0),
            Some(old),
            true,
            later,
            RESYNC_STUCK_RECOVER_AFTER,
            true,
        );
        assert!(still_advanced);
        assert!(!recover, "an episode that ever advanced must never recover");
    }

    #[test]
    fn mutual_sync_decision_never_advanced_recovers_after_window() {
        // `done` frozen at 0.0 since the episode began, past the window: the
        // true dual-reboot limbo. Recover.
        let now = std::time::Instant::now();
        let started = now - (RESYNC_STUCK_RECOVER_AFTER + Duration::from_secs(1));
        let (_, _, _, recover) = mutual_sync_decision(
            &mutual_sync_source(),
            Some(0.0),
            Some(started),
            false,
            now,
            RESYNC_STUCK_RECOVER_AFTER,
            true,
        );
        assert!(recover);
    }

    #[test]
    fn mutual_sync_decision_done_regression_starts_new_episode() {
        // `done` moving backward means DRBD restarted the resync: a new
        // attempt, so a new episode (fresh window, disqualification lifted).
        let now = std::time::Instant::now();
        let old = now - Duration::from_secs(3600);
        let mut s = mutual_sync_source();
        s.resync_done = Some(10.0);
        let (done, started, advanced, recover) = mutual_sync_decision(
            &s,
            Some(74.25),
            Some(old),
            true,
            now,
            RESYNC_STUCK_RECOVER_AFTER,
            true,
        );
        assert_eq!(done, Some(10.0));
        assert_eq!(started, Some(now), "regression restarts the episode clock");
        assert!(!advanced);
        assert!(!recover);
    }

    #[test]
    fn mutual_sync_decision_non_recoverer_never_acts() {
        // The higher-hostname node observes the same frozen episode but must
        // not act, so only one node force-reconnects.
        let now = std::time::Instant::now();
        let started = now - (RESYNC_STUCK_RECOVER_AFTER + Duration::from_secs(1));
        let (_, kept, _, recover) = mutual_sync_decision(
            &mutual_sync_source(),
            Some(0.0),
            Some(started),
            false,
            now,
            RESYNC_STUCK_RECOVER_AFTER,
            false,
        );
        assert!(!recover);
        // It still tracks the episode (so it never loses the clock).
        assert_eq!(kept, Some(started));
    }

    #[test]
    fn mutual_sync_decision_waits_within_window() {
        // Frozen, recoverer, but not yet past the window: keep waiting.
        let now = std::time::Instant::now();
        let started = now - Duration::from_secs(5);
        let (_, _, _, recover) = mutual_sync_decision(
            &mutual_sync_source(),
            Some(0.0),
            Some(started),
            false,
            now,
            RESYNC_STUCK_RECOVER_AFTER,
            true,
        );
        assert!(!recover);
    }

