    #[test]
    fn diverged_alert_states_the_weighed_counts_when_the_discount_decided() {
        use crate::drbd::GenId;
        // The node fenced while Primary returns with activity-log-inflated
        // bits; the survivor keeps.
        let survivor = GenId {
            current: 0xA9AE,
            bitmap: 0x100,
            history: [0x100, 0],
            bits: 34_312,
            flags: 0x120,
        };
        let fenced = GenId {
            current: 0x7870,
            bitmap: 0x100,
            history: [0x100, 0],
            bits: 912_384,
            flags: 0x22,
        };
        let b = diverged_alert_body("node-a", &survivor, &fenced);
        assert!(
            b.contains("crashed while Primary")
                && b.contains("~34312 blocks against ~0")
                && b.contains("raw counts 34312 vs 912384")
                && !b.contains("most un-replicated")
                && b.contains("Up to ~912384 blocks")
                && b.contains("served guest writes after the split")
                && !b.contains("likely"),
            "{b}"
        );
        // No discount involved: the plain wording.
        let a = GenId {
            flags: 0x120,
            ..fenced
        };
        let p = diverged_alert_body("node-b", &a, &survivor);
        assert!(
            p.contains("most un-replicated writes (~912384 vs ~34312")
                && p.contains("~34312 un-replicated blocks"),
            "{p}"
        );
    }

