    #[tokio::test(start_paused = true)]
    async fn split_brain_dual_master_never_discards_and_flags_wedge() {
        // Dual-master: both nodes believe they are master, so the peer never
        // discards and DRBD stays StandAlone after our reconnect attempt. The
        // master must never discard and, after repeated stuck attempts, must
        // recognise the dual-master wedge instead of looping silently.
        let start_called = std::sync::Arc::new(AtomicBool::new(false));
        let stop_called = std::sync::Arc::new(AtomicBool::new(false));
        let iscsi = SharedIscsi {
            start_called: start_called.clone(),
            stop_called: stop_called.clone(),
        };
        let drbd = std::sync::Arc::new(MockDrbd::new(dual_master_standalone()));

        let (mut sm, _) = StateMachine::new(
            test_config(),
            Box::new(ArcDrbd(drbd.clone())),
            Box::new(iscsi),
        );

        // Each tick keeps data as master but the peer does not resync.
        for _ in 0..DUAL_MASTER_WEDGE_ATTEMPTS {
            sm.resolve_split_brain_with_winner(Some(true)).await;
        }

        assert_eq!(
            sm.sb_keepdata_stuck, DUAL_MASTER_WEDGE_ATTEMPTS,
            "each stuck-as-master attempt must count toward the wedge"
        );
        assert!(
            !drbd.calls().contains(&"connect_discard"),
            "dual-master: must NEVER discard (both copies hold unique writes)"
        );
        assert!(
            !drbd.calls().contains(&"secondary"),
            "dual-master: must not demote toward a discard"
        );
        assert!(
            !stop_called.load(Ordering::Relaxed),
            "dual-master: must not stop iSCSI (no discard path taken)"
        );
        // A peer that is merely absent (Connecting, not StandAlone) must not be
        // mistaken for the wedge: the counter resets.
        drbd.set_status(connecting_secondary());
        sm.resolve_split_brain_with_winner(Some(true)).await;
        assert_eq!(
            sm.sb_keepdata_stuck, 0,
            "an absent (Connecting) peer is a normal wait, not the dual-master wedge"
        );
    }

    #[test]
    fn dual_master_autoheal_decision() {
        use super::{KEEPER_BACKSTOP_ATTEMPTS, WedgeAction, decide_wedge_action};
        let loser = Some(true); // "I rebooted into this split-brain"
        let survivor = Some(false);
        let a = KEEPER_BACKSTOP_ATTEMPTS;

        // Empty loser, non-keeper: yields immediately (the common reboot-path
        // loser). Attempts do not matter for the non-keeper.
        assert_eq!(
            decide_wedge_action(loser, Some(0), false, 3),
            WedgeAction::Yield
        );

        // Survivor (did not reboot into this): keeps, even with no VMs.
        assert_eq!(
            decide_wedge_action(survivor, Some(0), false, a),
            WedgeAction::KeepAndAlert
        );

        // VMs running: not a clear empty loser, so it keeps (the arbitrated
        // dual-run case that must never auto-discard).
        assert_eq!(
            decide_wedge_action(loser, Some(2), false, a),
            WedgeAction::KeepAndAlert
        );

        // Keeper backstop: an empty loser that is the keeper holds until the
        // wedge has persisted KEEPER_BACKSTOP_ATTEMPTS, then yields. A symmetric
        // case lets the non-keeper resolve first, but a keeper-isolated wedge
        // still heals instead of stranding.
        assert_eq!(
            decide_wedge_action(loser, Some(0), true, a - 1),
            WedgeAction::KeepAndAlert
        );
        assert_eq!(
            decide_wedge_action(loser, Some(0), true, a),
            WedgeAction::Yield
        );

        // Signals unavailable: keep (never auto-discard on doubt).
        assert_eq!(
            decide_wedge_action(None, Some(0), false, a),
            WedgeAction::KeepAndAlert
        );
        assert_eq!(
            decide_wedge_action(loser, None, false, a),
            WedgeAction::KeepAndAlert
        );
    }

    #[test]
    fn autoheal_restart_retry_is_bounded() {
        use super::{AUTOHEAL_MAX_RESTARTS, AUTOHEAL_REARM_AFTER_HOLDS, may_restart};

        // First attempt fires immediately.
        assert!(may_restart(0, 0));

        // Just fired, still master: hold (do not re-fire) until the patience
        // window elapses; then retry.
        assert!(!may_restart(1, 0));
        assert!(!may_restart(1, AUTOHEAL_REARM_AFTER_HOLDS - 1));
        assert!(may_restart(1, AUTOHEAL_REARM_AFTER_HOLDS));

        // Capped: after MAX_RESTARTS we never fire again, regardless of waiting.
        assert!(!may_restart(AUTOHEAL_MAX_RESTARTS, 0));
        assert!(!may_restart(
            AUTOHEAL_MAX_RESTARTS,
            AUTOHEAL_REARM_AFTER_HOLDS * 10
        ));
        // The last allowed retry is at MAX_RESTARTS - 1.
        assert!(may_restart(
            AUTOHEAL_MAX_RESTARTS - 1,
            AUTOHEAL_REARM_AFTER_HOLDS
        ));
    }

    #[tokio::test(start_paused = true)]
    async fn split_brain_loser_stops_iscsi_then_discards_in_order() {
        // The non-master must stop iSCSI before demoting and discarding (the
        // device must be closed for --discard-my-data), then resync. Status is
        // already Connected and Primary, so it restarts iSCSI with no
        // force-promote.
        let start_called = std::sync::Arc::new(AtomicBool::new(false));
        let stop_called = std::sync::Arc::new(AtomicBool::new(false));
        let iscsi = SharedIscsi {
            start_called: start_called.clone(),
            stop_called: stop_called.clone(),
        };
        let drbd = std::sync::Arc::new(MockDrbd::new(online_with_peer()));

        let (mut sm, _) = StateMachine::new(
            test_config(),
            Box::new(ArcDrbd(drbd.clone())),
            Box::new(iscsi),
        );

        sm.resolve_split_brain_with_winner(Some(false)).await;

        assert!(
            stop_called.load(Ordering::Relaxed),
            "loser must stop iSCSI so HA restarts its VMs on the winner"
        );
        assert_eq!(
            drbd.calls(),
            vec!["resume_io", "secondary", "connect_discard"],
            "loser must lift any I/O suspend (so the iSCSI teardown can't wedge), \
             then demote, then discard-and-resync, in that order; got {:?}",
            drbd.calls()
        );
        assert!(
            start_called.load(Ordering::Relaxed),
            "loser must restart iSCSI once resynced"
        );
    }

    // iSCSI mock whose stop reports the backstore as still exported.
    struct StuckBackstoreIscsi;

    #[async_trait::async_trait]
    impl IscsiControl for StuckBackstoreIscsi {
        async fn start(&mut self, _config: &Config) -> Result<()> {
            Ok(())
        }
        async fn stop(&mut self) -> Result<()> {
            anyhow::bail!(
                "iSCSI teardown incomplete (backstore delete failed): LIO may still hold the device"
            )
        }
    }

    #[tokio::test(start_paused = true)]
    async fn loser_never_discards_while_backstore_exported() {
        // A stop() error means LIO may still export this copy. Demoting and
        // discarding under it could switch the history of a session that
        // survived the portal close, so the round ends there.
        let drbd = std::sync::Arc::new(MockDrbd::new(online_with_peer()));
        let (mut sm, _) = StateMachine::new(
            test_config(),
            Box::new(ArcDrbd(drbd.clone())),
            Box::new(StuckBackstoreIscsi),
        );
        sm.resolve_split_brain_with_winner(Some(false)).await;
        let calls = drbd.calls();
        assert!(
            !calls.contains(&"secondary") && !calls.contains(&"connect_discard"),
            "no demote and no discard under a still-exported backstore; got {calls:?}"
        );
        assert!(
            !sm.loser_teardown_done,
            "owed guests must not start on the winner yet"
        );
    }

    #[test]
    fn cannot_go_online_body_categorizes_the_common_causes() {
        use super::cannot_go_online_alert_body;
        // Kernel-update brick: drbdadm cannot reach the module.
        let b = cannot_go_online_alert_body(
            "drbdadm status failed: Could not connect to 'drbd' generic netlink family",
            "4.19.0+1",
            7,
        );
        assert!(
            b.contains("kernel module") && b.contains("4.19.0+1"),
            "module-missing case must name the kernel: {b}"
        );
        // Broken config.
        let b = cannot_go_online_alert_body(
            "drbdadm up failed: resource twinstor-data: not defined in your config",
            "4.19.0+1",
            7,
        );
        assert!(b.contains("configuration is invalid"), "config case: {b}");
        // Anything else passes the raw error through.
        let b = cannot_go_online_alert_body("some novel failure", "4.19.0+1", 7);
        assert!(b.contains("some novel failure"), "passthrough case: {b}");
        // All variants state the impact.
        assert!(b.contains("without redundancy"));
    }

    #[test]
    fn tiebreaker_decision_rides_blips_but_flags_empty_immediately() {
        use super::{TIEBREAKER_UNREACHABLE_CHECKS, tiebreaker_decision};
        // Empty set is a configuration state: fire at once (not opted in).
        assert!(tiebreaker_decision(true, false, false, 0).1);
        // Empty set but the operator opted in with --allow-no-tiebreaker: stand
        // down, never fire, and leave the streak alone.
        assert_eq!(tiebreaker_decision(true, true, false, 3), (3, false));
        // Reachable resets the streak.
        assert_eq!(tiebreaker_decision(false, false, true, 2), (0, false));
        // Unreachable accumulates and fires only at the threshold.
        let mut streak = 0;
        for i in 1..=TIEBREAKER_UNREACHABLE_CHECKS {
            let (s, fire) = tiebreaker_decision(false, false, false, streak);
            streak = s;
            assert_eq!(
                fire,
                i >= TIEBREAKER_UNREACHABLE_CHECKS,
                "check {i} must {}fire",
                if i >= TIEBREAKER_UNREACHABLE_CHECKS {
                    ""
                } else {
                    "not "
                }
            );
        }
    }

    #[test]
    fn peer_daemon_down_requires_live_host_and_stale_existing_stamp() {
        use super::peer_daemon_down;
        let stale = 900;
        // Host up, stamp 20 min old.
        assert!(peer_daemon_down(Some(1000), 1000 + 1200, Some(true), stale));
        // No stamp at all: the peer may run an older version; never alert.
        assert!(!peer_daemon_down(None, 10_000, Some(true), stale));
        // Fresh stamp: healthy.
        assert!(!peer_daemon_down(Some(1000), 1000 + 60, Some(true), stale));
        // Host dead or unknown: the degraded watchdog owns it, no double alert.
        assert!(!peer_daemon_down(
            Some(1000),
            1000 + 1200,
            Some(false),
            stale
        ));
        assert!(!peer_daemon_down(Some(1000), 1000 + 1200, None, stale));
    }

    #[test]
    fn stuck_primary_demote_gating() {
        use super::{SUSPENDED_PRIMARY_DEMOTE_AFTER, should_demote_stuck_primary};
        let mut s = online_no_peer();
        s.role = Role::Primary;
        s.suspended_user = true;

        assert!(
            !should_demote_stuck_primary(&s, SUSPENDED_PRIMARY_DEMOTE_AFTER - 1),
            "must not demote before the abort threshold (could race the peer's own recovery)"
        );
        assert!(should_demote_stuck_primary(
            &s,
            SUSPENDED_PRIMARY_DEMOTE_AFTER
        ));

        s.suspended_user = false;
        assert!(
            !should_demote_stuck_primary(&s, SUSPENDED_PRIMARY_DEMOTE_AFTER),
            "a SERVING Primary must never be torn down by this path"
        );

        s.suspended_user = true;
        s.role = Role::Secondary;
        assert!(
            !should_demote_stuck_primary(&s, SUSPENDED_PRIMARY_DEMOTE_AFTER),
            "a Secondary needs no demote; the plain reconnect suffices"
        );
    }

    #[test]
    fn stuck_fence_rearm_window() {
        use super::{STUCK_PRIMARY_FENCE_REARM, stuck_fence_recent};
        let w = STUCK_PRIMARY_FENCE_REARM.as_secs();
        assert!(
            !stuck_fence_recent(None, 1_000_000),
            "no stamp: fence armed"
        );
        assert!(
            !stuck_fence_recent(Some("garbage"), 1_000_000),
            "unreadable stamp: fence armed"
        );
        assert!(
            stuck_fence_recent(Some("1000000"), 1_000_000 + w - 1),
            "within the window the fallback must hold, not reboot again"
        );
        assert!(!stuck_fence_recent(Some("1000000"), 1_000_000 + w));
    }

    #[tokio::test(start_paused = true)]
    async fn stuck_primary_demote_is_nondestructive_and_orders_teardown_first() {
        // The demote must stop iSCSI before demoting (the device must be
        // closed), must not lift the I/O suspend before replication is
        // re-established (suspended writes landing on one side would create a
        // divergence), and must never discard.
        let start_called = std::sync::Arc::new(AtomicBool::new(false));
        let stop_called = std::sync::Arc::new(AtomicBool::new(false));
        let iscsi = SharedIscsi {
            start_called: start_called.clone(),
            stop_called: stop_called.clone(),
        };
        // Status polls as Connected, so the post-demote wait sees the
        // reconnect land on its first pass and finishes the recovery.
        let drbd = std::sync::Arc::new(MockDrbd::new(online_with_peer()));

        let (mut sm, _) = StateMachine::new(
            test_config(),
            Box::new(ArcDrbd(drbd.clone())),
            Box::new(iscsi),
        );
        sm.sa_reconnect_attempted = true;
        sm.sa_aborted_reconnects = super::SUSPENDED_PRIMARY_DEMOTE_AFTER;

        sm.demote_stuck_suspended_primary().await;

        assert!(
            stop_called.load(Ordering::Relaxed),
            "target must be stopped so the demote can close the device"
        );
        assert_eq!(
            drbd.calls(),
            vec!["secondary", "connect", "resume_io"],
            "demote, NON-destructive connect, and the suspend lifted only after the \
             reconnect landed; got {:?}",
            drbd.calls()
        );
        assert!(
            start_called.load(Ordering::Relaxed),
            "target must be rebuilt once reconnected"
        );
        assert!(
            !sm.demote_target_down,
            "recovery finished, no leftover latch for the peer-connected edge"
        );
        assert_eq!(
            sm.sa_aborted_reconnects, 0,
            "episode bookkeeping must reset"
        );
    }

    #[tokio::test(start_paused = true)]
    async fn failed_alert_send_does_not_latch() {
        // `xe` is unavailable here, so every alert send fails, as it can in a
        // real split-brain while XAPI is down or restarting. A failed send must
        // not latch the alerted flags, so the next resolution tick retries and
        // the alert is not silently dropped.
        let drbd = std::sync::Arc::new(MockDrbd::new(online_with_peer()));
        let (mut sm, _) = StateMachine::new(
            test_config(),
            Box::new(ArcDrbd(drbd.clone())),
            Box::new(MockIscsi::new()),
        );

        sm.resolve_split_brain_with_winner(None).await;
        assert!(
            !sm.sb_undecidable_alerted,
            "undecidable alert failed to send, must stay unlatched for retry"
        );

        sm.resolve_split_brain_with_winner(Some(true)).await;
        assert!(
            !sm.sb_resolved_alerted,
            "resolved alert failed to send, must stay unlatched for retry"
        );
    }

    #[tokio::test]
    async fn failed_redundancy_alert_send_does_not_latch() {
        // `xe` is unavailable here, so the send fails. Losing the peer is when
        // it fails for real: if the dead node was the pool master, the
        // survivor's xe has no master until XHA elects it and XAPI restarts.
        // The latch must stay unset so the next tick retries instead of
        // waiting out the 24 h re-raise.
        let drbd = std::sync::Arc::new(MockDrbd::new(online_with_peer()));
        let (mut sm, _) = StateMachine::new(
            test_config(),
            Box::new(ArcDrbd(drbd.clone())),
            Box::new(MockIscsi::new()),
        );

        // Peer lost well past the debounce grace: this tick must try to alert.
        sm.peer_lost_since = Some(std::time::Instant::now() - Duration::from_secs(3600));
        sm.check_redundancy(true, false).await;
        assert!(
            sm.redundancy_alert_at.is_none(),
            "redundancy alert failed to send, must stay unlatched for retry"
        );
    }

    #[tokio::test(start_paused = true)]
    async fn undecidable_alert_does_not_suppress_resolved_alert() {
        // The undecidable ("manual review required") and resolved
        // ("auto-resolved") alerts need separate latches. With a shared latch,
        // a delivered undecidable alert would suppress the resolution alert and
        // the operator would still believe manual review is required.
        let drbd = std::sync::Arc::new(MockDrbd::new(online_with_peer()));
        let (mut sm, _) = StateMachine::new(
            test_config(),
            Box::new(ArcDrbd(drbd.clone())),
            Box::new(MockIscsi::new()),
        );

        // Pretend the undecidable alert was delivered on an earlier tick.
        sm.sb_undecidable_alerted = true;

        // Winner resolution completes (status is Connected, so the confirm
        // loop succeeds and the episode ends): both latches must be reset so a
        // future episode alerts again. The resolved alert was attempted (the
        // send fails here without `xe`), so the undecidable latch did not gate
        // it.
        sm.resolve_split_brain_with_winner(Some(true)).await;
        assert!(
            !sm.sb_undecidable_alerted && !sm.sb_resolved_alerted,
            "episode end must reset both alert latches"
        );
    }

    #[tokio::test]
    async fn stale_marker_cleared_once_cluster_healthy() {
        // A marker surviving into a fully healthy cluster (Connected, both
        // UpToDate) is stale: the resync that follows a resolution has
        // completed. It must be swept, or the next ordinary disconnect is
        // treated as a split-brain and could discard legitimate writes on the
        // non-master. This happens when the winner's confirm window misses the
        // reconnect, for example while the loser is in a fence reboot.
        let marker = std::env::temp_dir().join("twinstor-test-stale-marker");
        std::fs::write(&marker, "stale marker resource=twinstor-data").unwrap();

        let drbd = std::sync::Arc::new(MockDrbd::new(online_with_peer()));
        let (mut sm, _) = StateMachine::new(
            test_config(),
            Box::new(ArcDrbd(drbd.clone())),
            Box::new(MockIscsi::new()),
        );
        sm.marker_path = marker.to_string_lossy().to_string();
        sm.sb_resolved_alerted = true; // left over from the resolved episode

        let (shutdown_tx, shutdown_rx) = tokio::sync::broadcast::channel(1);
        let sm_handle = tokio::spawn(async move {
            sm.run(shutdown_rx).await.unwrap();
            sm
        });
        tokio::time::sleep(Duration::from_millis(200)).await;
        let _ = shutdown_tx.send(());
        let sm = sm_handle.await.unwrap();

        assert!(
            !marker.exists(),
            "stale marker must be cleared once the cluster is Connected + UpToDate/UpToDate"
        );
        assert!(
            !sm.sb_resolved_alerted,
            "alert latches must reset when the stale marker is swept"
        );
    }

    #[tokio::test(start_paused = true)]
    async fn yielded_suspended_node_resolves_as_loser() {
        // Frozen ex-master: this node's fence-peer yielded (marker on disk)
        // and its I/O is still suspended, but its stale pool.conf (or a hung
        // xapi) reports it as master. The yield overrules the role lookup: the
        // node served nobody while frozen, so it discards and resyncs instead
        // of deadlocking the resolution as a second winner.
        let yield_file = std::env::temp_dir().join("twinstor-test-yield-loser");
        std::fs::write(&yield_file, "2026-01-01 00:00:00").unwrap();
        let sb_marker = std::env::temp_dir().join("twinstor-test-yield-loser-sb");
        std::fs::write(&sb_marker, "resource=twinstor-data").unwrap();

        let mut status = online_with_peer();
        status.suspended_user = true;
        let drbd = std::sync::Arc::new(MockDrbd::new(status));
        let (mut sm, _) = StateMachine::new(
            test_config(),
            Box::new(ArcDrbd(drbd.clone())),
            Box::new(MockIscsi::new()),
        );
        sm.yield_path = yield_file.to_string_lossy().to_string();
        sm.marker_path = sb_marker.to_string_lossy().to_string();
        let latch = std::env::temp_dir().join("twinstor-test-yield-loser-latch");
        sm.latch_path = latch.to_string_lossy().to_string();

        sm.resolve_split_brain().await;

        assert!(
            drbd.calls().contains(&"connect_discard"),
            "a yielded, still-suspended node must resolve as the loser and discard; \
             calls: {:?}",
            drbd.calls()
        );
        assert!(
            !yield_file.exists(),
            "the yield marker must be consumed once the loser resolution converges"
        );
        assert!(
            !latch.exists(),
            "the latched verdict must be consumed once the loser resolution converges"
        );
        let _ = std::fs::remove_file(&sb_marker);
    }

    #[tokio::test(start_paused = true)]
    async fn yield_marker_without_suspend_does_not_force_discard() {
        // A yield marker alone is not enough: if the I/O suspend was lifted
        // (the node may have served writes since), the ordinary winner
        // determination must run. On this test host it is undecidable (no
        // xe, no pool.conf), so nothing may be discarded.
        let yield_file = std::env::temp_dir().join("twinstor-test-yield-stale");
        std::fs::write(&yield_file, "2026-01-01 00:00:00").unwrap();

        let drbd = std::sync::Arc::new(MockDrbd::new(online_with_peer()));
        let (mut sm, _) = StateMachine::new(
            test_config(),
            Box::new(ArcDrbd(drbd.clone())),
            Box::new(MockIscsi::new()),
        );
        sm.yield_path = yield_file.to_string_lossy().to_string();
        sm.latch_path = std::env::temp_dir()
            .join("twinstor-test-yield-stale-latch")
            .to_string_lossy()
            .to_string();

        sm.resolve_split_brain().await;

        assert!(
            !drbd.calls().contains(&"connect_discard"),
            "without the suspend the yield is stale evidence and must never force a \
             discard; calls: {:?}",
            drbd.calls()
        );
        let _ = std::fs::remove_file(&yield_file);
    }

    #[tokio::test(start_paused = true)]
    async fn yield_verdict_latches_and_holds_down_across_rounds() {
        // The yielded loser's first discard round can find nobody listening
        // (the peer's resolver runs on its own grace timer). The verdict must
        // survive that round (the attempt consumes the suspend it was verified
        // against), and the node must hold itself down instead of re-serving
        // stale data.
        let yield_file = std::env::temp_dir().join("twinstor-test-yield-latch-y");
        std::fs::write(&yield_file, "2026-01-01 00:00:00").unwrap();
        let sb_marker = std::env::temp_dir().join("twinstor-test-yield-latch-sb");
        std::fs::write(&sb_marker, "resource=twinstor-data").unwrap();
        let latch = std::env::temp_dir().join("twinstor-test-yield-latch-l");
        let _ = std::fs::remove_file(&latch);

        // Round 1: suspended, but the peer never appears (stays Connecting).
        let mut status = online_with_peer();
        status.suspended_user = true;
        status.connection = crate::drbd::ConnectionState::Connecting;
        let drbd = std::sync::Arc::new(MockDrbd::new(status.clone()));
        *drbd.current_uuid.lock().unwrap() = Some(0xABC0);
        let (mut sm, _) = StateMachine::new(
            test_config(),
            Box::new(ArcDrbd(drbd.clone())),
            Box::new(MockIscsi::new()),
        );
        sm.yield_path = yield_file.to_string_lossy().to_string();
        sm.marker_path = sb_marker.to_string_lossy().to_string();
        sm.latch_path = latch.to_string_lossy().to_string();

        sm.resolve_split_brain().await;

        assert!(
            latch.exists(),
            "the suspend-verified verdict must be latched on disk"
        );
        let calls = drbd.calls();
        assert!(calls.contains(&"connect_discard"), "calls: {calls:?}");
        assert!(
            !calls.contains(&"disconnect_force"),
            "a latched loser whose round finds no taker must leave the discard \
             offer PARKED in Connecting, never disconnect and phase-miss \
             the winner; calls: {calls:?}"
        );
        assert!(
            !calls.contains(&"force_primary"),
            "a latched loser must never re-promote between rounds (it would \
             serve stale data); calls: {calls:?}"
        );
        assert!(
            sm.discard_offer_since.is_some(),
            "the standing offer must be armed after a no-taker round"
        );

        // Round 2: the offer holds while the peer is still absent. The tick
        // hook owns the tick; the discard must not be re-issued.
        let mut status2 = online_with_peer();
        status2.suspended_user = false;
        status2.connection = crate::drbd::ConnectionState::Connecting;
        drbd.set_status(status2.clone());
        assert!(
            sm.poll_standing_discard_offer(&status2, true).await,
            "a parked offer must consume the tick while holding"
        );
        assert_eq!(
            drbd.calls()
                .iter()
                .filter(|c| **c == "connect_discard")
                .count(),
            1,
            "the parked offer must not be re-issued every tick; calls: {:?}",
            drbd.calls()
        );

        // Round 3: the winner reconnects (Connected) and the standing offer
        // converges: target restarted, every episode marker consumed.
        let mut status3 = online_with_peer();
        status3.connection = crate::drbd::ConnectionState::Connected;
        drbd.set_status(status3.clone());
        assert!(
            sm.poll_standing_discard_offer(&status3, true).await,
            "the taken offer must finish the convergence"
        );
        assert!(
            !yield_file.exists() && !latch.exists(),
            "yield + latch must be consumed when the loser resolution converges"
        );
        assert!(
            sm.discard_offer_since.is_none(),
            "the offer must be disarmed on convergence"
        );
        let _ = std::fs::remove_file(&sb_marker);
    }

    #[test]
    fn standing_offer_decision_matrix() {
        use OfferAction::*;
        assert_eq!(
            standing_offer_decision(false, ConnectionState::Connecting),
            NotArmed
        );
        assert_eq!(
            standing_offer_decision(false, ConnectionState::Connected),
            NotArmed
        );
        assert_eq!(
            standing_offer_decision(true, ConnectionState::Connecting),
            Hold
        );
        assert_eq!(
            standing_offer_decision(true, ConnectionState::Unknown),
            Hold
        );
        assert_eq!(
            standing_offer_decision(true, ConnectionState::Disconnecting),
            Hold
        );
        assert_eq!(
            standing_offer_decision(true, ConnectionState::Connected),
            Finish
        );
        assert_eq!(
            standing_offer_decision(true, ConnectionState::StandAlone),
            Rearm
        );
    }

    #[tokio::test(start_paused = true)]
    async fn standing_offer_rearms_after_standalone() {
        // The peer refused the parked offer (or an operator intervened): the
        // resource lands StandAlone. The hook must disarm and hand the tick
        // back so the ordinary resolver re-offers.
        let drbd = std::sync::Arc::new(MockDrbd::new(starting_secondary()));
        let (mut sm, _) = StateMachine::new(
            test_config(),
            Box::new(ArcDrbd(drbd.clone())),
            Box::new(MockIscsi::new()),
        );
        sm.discard_offer_since = Some(std::time::Instant::now());
        let mut s = starting_secondary();
        s.connection = crate::drbd::ConnectionState::StandAlone;
        assert!(
            !sm.poll_standing_discard_offer(&s, true).await,
            "a StandAlone abort must hand the tick back to the resolver"
        );
        assert!(
            sm.discard_offer_since.is_none(),
            "the offer must be disarmed"
        );
        assert!(
            drbd.calls().is_empty(),
            "rearm itself must not touch DRBD; calls: {:?}",
            drbd.calls()
        );
    }

    #[tokio::test(start_paused = true)]
    async fn standing_offer_readopted_after_daemon_restart() {
        // A daemon restart loses the in-memory arm while the kernel still
        // holds the parked discard connect. The episode markers (latch and
        // split-brain marker) plus Connecting identify it; the hook re-adopts
        // instead of falling through to the StandAlone machinery.
        let sb_marker = std::env::temp_dir().join("twinstor-test-readopt-sb");
        std::fs::write(&sb_marker, "resource=twinstor-data").unwrap();
        let latch = std::env::temp_dir().join("twinstor-test-readopt-l");
        std::fs::write(&latch, "latched").unwrap();

        let mut s = online_with_peer();
        s.connection = crate::drbd::ConnectionState::Connecting;
        let drbd = std::sync::Arc::new(MockDrbd::new(s.clone()));
        let (mut sm, _) = StateMachine::new(
            test_config(),
            Box::new(ArcDrbd(drbd.clone())),
            Box::new(MockIscsi::new()),
        );
        sm.marker_path = sb_marker.to_string_lossy().to_string();
        sm.latch_path = latch.to_string_lossy().to_string();

        assert!(
            sm.poll_standing_discard_offer(&s, true).await,
            "a restart-orphaned parked offer must be re-adopted and held"
        );
        assert!(sm.discard_offer_since.is_some());
        let _ = std::fs::remove_file(&sb_marker);
        let _ = std::fs::remove_file(&latch);
    }

    // Sample `calldaemon query_liveset` XML: local=AAA, peer=BBB, with the peer's
    // liveness and statefile access as parameters. Matches the real format.
    fn liveset_xml(status: &str, peer_live: &str, peer_sf: &str) -> String {
        format!(
            r#"<?xml version="1.0" encoding="UTF-8"?>
<ha_liveset_info version="1.0">
  <status>{status}</status>
  <localhost>
    <HostID>AAAAAAAA-0000-0000-0000-000000000000</HostID>
    <HostIndex>0</HostIndex>
  </localhost>
  <host>
    <HostID>AAAAAAAA-0000-0000-0000-000000000000</HostID>
    <liveness>TRUE</liveness>
    <master>FALSE</master>
    <statefile_access>TRUE</statefile_access>
  </host>
  <host>
    <HostID>BBBBBBBB-1111-1111-1111-111111111111</HostID>
    <liveness>{peer_live}</liveness>
    <master>TRUE</master>
    <statefile_access>{peer_sf}</statefile_access>
  </host>
  <raw_status_on_local_host>
    <statefile_latency>1</statefile_latency>
  </raw_status_on_local_host>
</ha_liveset_info>"#
        )
    }
    // The predicate peer_dead_via_liveset applies to the parsed result.
    fn liveset_says_dead(xml: &str) -> Option<bool> {
        parse_peer_liveset(xml).map(|l| l.local_online && !l.peer_live && !l.peer_statefile_access)
    }

    #[test]
    fn parse_peer_liveset_cases() {
        // Both live (steady state): peer present, not dead.
        let l = parse_peer_liveset(&liveset_xml("Online", "TRUE", "TRUE")).unwrap();
        assert!(l.local_online && l.peer_live && l.peer_statefile_access);
        assert_eq!(
            liveset_says_dead(&liveset_xml("Online", "TRUE", "TRUE")),
            Some(false)
        );
        // Peer gone (powered off or fenced): not live and off the statefile
        // while I am Online, so confirmed dead.
        assert_eq!(
            liveset_says_dead(&liveset_xml("Online", "FALSE", "FALSE")),
            Some(true)
        );
        // Peer switch-isolated but alive: it still reaches the statefile over
        // the direct link, so not confirmed dead.
        assert_eq!(
            liveset_says_dead(&liveset_xml("Online", "FALSE", "TRUE")),
            Some(false)
        );
        assert_eq!(
            liveset_says_dead(&liveset_xml("Online", "TRUE", "FALSE")),
            Some(false)
        );
        // I am the isolated side (not Online): never claim the peer is dead.
        assert_eq!(
            liveset_says_dead(&liveset_xml("Starting", "FALSE", "FALSE")),
            Some(false)
        );
        // The peer is the non-local <host>: the local entry is excluded, so the
        // peer here reads not live and off the statefile.
        let l2 = parse_peer_liveset(&liveset_xml("Online", "FALSE", "FALSE")).unwrap();
        assert!(!l2.peer_live && !l2.peer_statefile_access);
        // Malformed or missing peer: None, so the caller holds.
        assert_eq!(
            parse_peer_liveset("<ha_liveset_info></ha_liveset_info>"),
            Option::None
        );
        assert_eq!(parse_peer_liveset(""), Option::None);
    }

    // Real `calldaemon query_liveset` output from a dom0, with peer liveness
    // and statefile access parameterized. Guards against a format drift that
    // would silently turn peer_dead_via_liveset into None. The tricky part is
    // <raw_status_on_local_host>: its <host_raw_data> blocks carry their own
    // <HostID> and must not be taken for <host> entries (the split key is the
    // literal "<host>", which "<host_raw_data>" does not contain).
    fn real_liveset_xml(peer_live: &str, peer_sf: &str) -> String {
        format!(
            r#"<?xml version="1.0" encoding="UTF-8"?>
<ha_liveset_info version="1.0">
  <status>Online</status>
  <localhost>
    <HostID>5e5e0006-0000-4000-8000-000000000006</HostID>
    <HostIndex>0</HostIndex>
  </localhost>
  <host>
    <HostID>5e5e0006-0000-4000-8000-000000000006</HostID>
    <HostIndex>0</HostIndex>
    <liveness>TRUE</liveness>
    <master>FALSE</master>
    <statefile_access>TRUE</statefile_access>
    <statefile_corrupted>FALSE</statefile_corrupted>
    <excluded>FALSE</excluded>
  </host>
  <host>
    <HostID>5e5e0007-0000-4000-8000-000000000007</HostID>
    <HostIndex>1</HostIndex>
    <liveness>{peer_live}</liveness>
    <master>TRUE</master>
    <statefile_access>{peer_sf}</statefile_access>
    <statefile_corrupted>FALSE</statefile_corrupted>
    <excluded>FALSE</excluded>
  </host>
  <raw_status_on_local_host>
    <statefile_latency>1</statefile_latency>
    <host_raw_data>
      <HostID>5e5e0006-0000-4000-8000-000000000006</HostID>
      <HostIndex>0</HostIndex>
      <time_since_last_update_on_statefile>1</time_since_last_update_on_statefile>
    </host_raw_data>
    <host_raw_data>
      <HostID>5e5e0007-0000-4000-8000-000000000007</HostID>
      <HostIndex>1</HostIndex>
      <time_since_last_update_on_statefile>4877</time_since_last_update_on_statefile>
    </host_raw_data>
  </raw_status_on_local_host>
  <timeout>
    <T1>90000</T1>
  </timeout>
</ha_liveset_info>"#
        )
    }

    #[test]
    fn parse_peer_liveset_real_format() {
        // Healthy output: peer (48c7ac1c) live and on the statefile, so not dead.
        let l = parse_peer_liveset(&real_liveset_xml("TRUE", "TRUE")).unwrap();
        assert!(l.local_online, "top-level <status>Online must parse");
        assert!(
            l.peer_live && l.peer_statefile_access,
            "the peer <host> block, not a <host_raw_data> block, must be read"
        );
        assert_eq!(
            liveset_says_dead(&real_liveset_xml("TRUE", "TRUE")),
            Some(false)
        );
        // Peer powered off: not live and off the statefile, so dead.
        assert_eq!(
            liveset_says_dead(&real_liveset_xml("FALSE", "FALSE")),
            Some(true)
        );
        // <host_raw_data> blocks (with their own HostID, after the real <host>
        // entries) must not add spurious hosts or trip the two-host guard.
        assert!(parse_peer_liveset(&real_liveset_xml("FALSE", "FALSE")).is_some());

        // A third <host> (a lingering evicted host, or an add/eject transient)
        // makes the peer ambiguous: None, so the caller holds instead of reading
        // a stray entry's liveness as the peer's.
        let three_hosts = real_liveset_xml("TRUE", "TRUE").replace(
            "  <raw_status_on_local_host>",
            "  <host>\n    <HostID>cccccccc-2222-2222-2222-222222222222</HostID>\n    \
             <liveness>FALSE</liveness>\n    <statefile_access>FALSE</statefile_access>\n  \
             </host>\n  <raw_status_on_local_host>",
        );
        assert_eq!(
            parse_peer_liveset(&three_hosts),
            Option::None,
            "more than one non-local host must return None (ambiguous peer)"
        );
    }

    #[test]
    fn masterless_decision_matrix() {
        use MasterlessAction::*;
        let now = std::time::Instant::now();
        let fresh = now - Duration::from_secs(30);
        let past_alert = now - (MASTERLESS_ALERT_AFTER + Duration::from_secs(1));
        let past_recover = now - (MASTERLESS_RECOVER_AFTER + Duration::from_secs(1));

        // args after last_recover: storage_healthy, peer_reachable,
        // peer_is_live_master, peer_confirmed_dead, confirmed_dead_since,
        // local_uptodate, now, confirm_stable. `S` is the confirm_stable window;
        // `None` for confirmed_dead_since keeps the fast promote dormant, so the
        // first cases exercise only the classic path.
        let s = CONFIRMED_DEAD_PROMOTE_STABLE;
        let h = FATESHARED_CONFIRMED_DEAD_HOLD;
        // All cases below pass discriminator_reliable=true (arbitrated), so the
        // hold grace `h` is inert.
        let cd_stable = now - (s + Duration::from_secs(1)); // conjunction held long enough
        // Sane role: clear.
        assert_eq!(
            masterless_decision(
                false,
                Some(past_recover),
                true,
                Option::None,
                true,
                true,
                false,
                false,
                Option::None,
                false,
                now,
                s,
                true,
                h,
                true
            ),
            None
        );
        // First sample / young window: hold (xapi may be mid-transition).
        assert_eq!(
            masterless_decision(
                true,
                Option::None,
                false,
                Option::None,
                true,
                true,
                false,
                false,
                Option::None,
                false,
                now,
                s,
                true,
                h,
                true
            ),
            Hold
        );
        assert_eq!(
            masterless_decision(
                true,
                Some(fresh),
                false,
                Option::None,
                true,
                true,
                false,
                false,
                Option::None,
                false,
                now,
                s,
                true,
                h,
                true
            ),
            Hold
        );
        // Past the alert threshold, not yet alerted: alert first.
        assert_eq!(
            masterless_decision(
                true,
                Some(past_alert),
                false,
                Option::None,
                true,
                true,
                false,
                false,
                Option::None,
                false,
                now,
                s,
                true,
                h,
                true
            ),
            Alert
        );
        // Past the recovery threshold with all guards (peer present, healthy): recover.
        assert_eq!(
            masterless_decision(
                true,
                Some(past_recover),
                true,
                Option::None,
                true,
                true,
                false,
                false,
                Option::None,
                false,
                now,
                s,
                true,
                h,
                true
            ),
            Recover
        );
        // Normal-path guards unmet and peer not confirmed dead: hold, never guess.
        assert_eq!(
            masterless_decision(
                true,
                Some(past_recover),
                true,
                Option::None,
                false,
                true,
                false,
                false,
                Option::None,
                false,
                now,
                s,
                true,
                h,
                true
            ),
            Hold
        );
        assert_eq!(
            masterless_decision(
                true,
                Some(past_recover),
                true,
                Option::None,
                true,
                false,
                false,
                false,
                Option::None,
                false,
                now,
                s,
                true,
                h,
                true
            ),
            Hold
        );
        // Cooldown: one attempt per hour.
        assert_eq!(
            masterless_decision(
                true,
                Some(past_recover),
                true,
                Some(now - Duration::from_secs(60)),
                true,
                true,
                false,
                false,
                Option::None,
                false,
                now,
                s,
                true,
                h,
                true
            ),
            Hold
        );
        assert_eq!(
            masterless_decision(
                true,
                Some(past_recover),
                true,
                Some(now - (MASTERLESS_RECOVER_COOLDOWN + Duration::from_secs(1))),
                true,
                true,
                false,
                false,
                Option::None,
                false,
                now,
                s,
                true,
                h,
                true
            ),
            Recover
        );
        // Peer is a live master: defer, never transition.
        assert_eq!(
            masterless_decision(
                true,
                Some(past_recover),
                true,
                Option::None,
                true,
                true,
                true,
                false,
                Option::None,
                false,
                now,
                s,
                true,
                h,
                true
            ),
            DeferToMaster
        );
        assert_eq!(
            masterless_decision(
                true,
                Some(past_alert),
                false,
                Option::None,
                true,
                true,
                true,
                false,
                Option::None,
                false,
                now,
                s,
                true,
                h,
                true
            ),
            DeferToMaster
        );

        // Lone-survivor path (classic 300 s): peer confirmed dead and my copy
        // UpToDate, with storage_healthy=false and peer_reachable=false (both
        // unsatisfiable while the peer is dead): transition alone. No
        // confirmed_dead_since, so this is the classic path, not the fast one.
        assert_eq!(
            masterless_decision(
                true,
                Some(past_recover),
                true,
                Option::None,
                false,
                false,
                false,
                true,
                Option::None,
                true,
                now,
                s,
                true,
                h,
                true
            ),
            Recover
        );
        // Peer confirmed dead but my copy not UpToDate: hold. There is no
        // authoritative copy to serve; never transition on a stale disk.
        assert_eq!(
            masterless_decision(
                true,
                Some(past_recover),
                true,
                Option::None,
                false,
                false,
                false,
                true,
                Option::None,
                false,
                now,
                s,
                true,
                h,
                true
            ),
            Hold
        );
        // Peer not confirmed dead (transiently unreachable, say) and degraded:
        // hold, so a blip cannot mint a second master.
        assert_eq!(
            masterless_decision(
                true,
                Some(past_recover),
                true,
                Option::None,
                false,
                false,
                false,
                false,
                Option::None,
                true,
                now,
                s,
                true,
                h,
                true
            ),
            Hold
        );

        // Fast confirmed-dead promote. The masterless window is still young (well
        // under the 300 s classic recover), so a Recover here can only come from
        // the fast path driven by confirmed_dead_since.
        // Confirmed dead, stable, my copy UpToDate: promote now.
        assert_eq!(
            masterless_decision(
                true,
                Some(fresh),
                false,
                Option::None,
                false,
                false,
                false,
                true,
                Some(cd_stable),
                true,
                now,
                s,
                true,
                h,
                true
            ),
            Recover
        );
        // Confirmed dead but not yet stable (clock just opened): hold until it matures.
        assert_eq!(
            masterless_decision(
                true,
                Some(fresh),
                false,
                Option::None,
                false,
                false,
                false,
                true,
                Some(now - Duration::from_secs(5)),
                true,
                now,
                s,
                true,
                h,
                true
            ),
            Hold
        );
        // Confirmed dead and stable but my copy not UpToDate: never promote a
        // non-authoritative copy, however dead the peer is.
        assert_eq!(
            masterless_decision(
                true,
                Some(fresh),
                false,
                Option::None,
                false,
                false,
                false,
                true,
                Some(cd_stable),
                false,
                now,
                s,
                true,
                h,
                true
            ),
            Hold
        );
        // Fast path respects the recover cooldown too.
        assert_eq!(
            masterless_decision(
                true,
                Some(fresh),
                false,
                Some(now - Duration::from_secs(60)),
                false,
                false,
                false,
                true,
                Some(cd_stable),
                true,
                now,
                s,
                true,
                h,
                true
            ),
            Hold
        );
        // Stale clock but peer_confirmed_dead=false this tick (a signal blipped
        // back to life): the branch's peer_confirmed_dead guard blocks the promote.
        assert_eq!(
            masterless_decision(
                true,
                Some(fresh),
                false,
                Option::None,
                false,
                false,
                false,
                false,
                Some(cd_stable),
                true,
                now,
                s,
                true,
                h,
                true
            ),
            Hold
        );
        // A live master wins over a stale confirmed-dead clock: defer, never promote.
        assert_eq!(
            masterless_decision(
                true,
                Some(fresh),
                false,
                Option::None,
                false,
                false,
                true,
                true,
                Some(cd_stable),
                true,
                now,
                s,
                true,
                h,
                true
            ),
            DeferToMaster
        );

        // Fate-shared (discriminator_reliable=false). The dead-versus-isolated
        // signal is unreliable, so a confirmed-dead peer must wait out the long
        // hold grace `h` before any promote: an isolated but alive peer can
        // return within it. cd_stable (past the 45 s arbitrated grace) is not
        // enough; cd_held (past `h`) is.
        let cd_held = now - (h + Duration::from_secs(1));
        // Fast path in fate-shared: confirmed dead, past the arbitrated 45 s
        // stable window but well under the hold grace: hold (arbitrated recovers).
        assert_eq!(
            masterless_decision(
                true,
                Some(fresh),
                false,
                Option::None,
                false,
                false,
                false,
                true,
                Some(cd_stable),
                true,
                now,
                s,
                false,
                h,
                true
            ),
            Hold
        );
        // Same inputs but arbitrated: Recover, so the mode is the only difference.
        assert_eq!(
            masterless_decision(
                true,
                Some(fresh),
                false,
                Option::None,
                false,
                false,
                false,
                true,
                Some(cd_stable),
                true,
                now,
                s,
                true,
                h,
                true
            ),
            Recover
        );
        // Fate-shared, confirmed dead past the long grace: promote (assume real
        // death, so automatic recovery still happens).
        assert_eq!(
            masterless_decision(
                true,
                Some(fresh),
                false,
                Option::None,
                false,
                false,
                false,
                true,
                Some(cd_held),
                true,
                now,
                s,
                false,
                h,
                true
            ),
            Recover
        );
        // Classic 300 s lone-survivor path in fate-shared: masterless window past
        // recover, confirmed dead, not yet past the hold grace: hold. The long
        // grace gates the classic path too.
        assert_eq!(
            masterless_decision(
                true,
                Some(past_recover),
                true,
                Option::None,
                false,
                false,
                false,
                true,
                Some(cd_stable),
                true,
                now,
                s,
                false,
                h,
                true
            ),
            Hold
        );
        // Same, once past the hold grace: Recover.
        assert_eq!(
            masterless_decision(
                true,
                Some(past_recover),
                true,
                Option::None,
                false,
                false,
                false,
                true,
                Some(cd_held),
                true,
                now,
                s,
                false,
                h,
                true
            ),
            Recover
        );
        // Fate-shared still alerts during the hold, so the operator can step in early.
        assert_eq!(
            masterless_decision(
                true,
                Some(past_alert),
                false,
                Option::None,
                false,
                false,
                false,
                true,
                Some(cd_stable),
                true,
                now,
                s,
                false,
                h,
                true
            ),
            Alert
        );
        // Fate-shared still defers to a live master.
        assert_eq!(
            masterless_decision(
                true,
                Some(past_recover),
                true,
                Option::None,
                false,
                false,
                true,
                true,
                Some(cd_held),
                true,
                now,
                s,
                false,
                h,
                true
            ),
            DeferToMaster
        );

        // Symmetric masterless tiebreak. Both alive, both slave-of-self, storage
        // healthy and peer reachable, past the recover window. The keeper
        // (i_am_lower=true) promotes; the non-keeper (i_am_lower=false) holds
        // and waits to re-adopt, so the pair cannot mint two masters.
        assert_eq!(
            masterless_decision(
                true,
                Some(past_recover),
                true,
                Option::None,
                true,
                true,
                false,
                false,
                Option::None,
                false,
                now,
                s,
                true,
                h,
                true
            ),
            Recover
        );
        assert_eq!(
            masterless_decision(
                true,
                Some(past_recover),
                true,
                Option::None,
                true,
                true,
                false,
                false,
                Option::None,
                false,
                now,
                s,
                true,
                h,
                false
            ),
            Hold
        );
        // The tiebreak does not gate the lone-survivor promote: with the peer
        // confirmed dead and my copy UpToDate, even the non-keeper promotes (a
        // survivor cannot wait for a dead keeper). Classic and fast paths alike.
        assert_eq!(
            masterless_decision(
                true,
                Some(past_recover),
                true,
                Option::None,
                false,
                false,
                false,
                true,
                Option::None,
                true,
                now,
                s,
                true,
                h,
                false
            ),
            Recover
        );
        assert_eq!(
            masterless_decision(
                true,
                Some(fresh),
                false,
                Option::None,
                false,
                false,
                false,
                true,
                Some(cd_stable),
                true,
                now,
                s,
                true,
                h,
                false
            ),
            Recover
        );
    }

    #[test]
    fn defer_rejoin_ladder() {
        use StrandedAction::*;
        let now = std::time::Instant::now();
        let grace = Duration::from_secs(90);
        let retry = Duration::from_secs(180);
        let within_grace = now - Duration::from_secs(30);
        let past_grace = now - Duration::from_secs(91);
        // Not deferring: clear (the repoint took / role sane again).
        assert_eq!(
            defer_rejoin_decision(false, Some(past_grace), None, 0, now, grace, retry, 3),
            Clear
        );
        // First deferring sample: open the grace window.
        assert_eq!(
            defer_rejoin_decision(true, None, None, 0, now, grace, retry, 3),
            StartTimer
        );
        // Inside the grace window: idle, let recover-slaves try first.
        assert_eq!(
            defer_rejoin_decision(true, Some(within_grace), None, 0, now, grace, retry, 3),
            Idle
        );
        // Past grace, never repointed: repoint now.
        assert_eq!(
            defer_rejoin_decision(true, Some(past_grace), None, 0, now, grace, retry, 3),
            Restart
        );
        // Past grace, repointed recently: wait out the retry interval.
        assert_eq!(
            defer_rejoin_decision(
                true,
                Some(past_grace),
                Some(now - Duration::from_secs(60)),
                1,
                now,
                grace,
                retry,
                3
            ),
            Idle
        );
        // Past grace, retry interval elapsed, under the cap: repoint again.
        assert_eq!(
            defer_rejoin_decision(
                true,
                Some(past_grace),
                Some(now - Duration::from_secs(181)),
                1,
                now,
                grace,
                retry,
                3
            ),
            Restart
        );
        // Cap reached: give up, alert the operator.
        assert_eq!(
            defer_rejoin_decision(
                true,
                Some(past_grace),
                Some(now - Duration::from_secs(181)),
                3,
                now,
                grace,
                retry,
                3
            ),
            GiveUp
        );
    }

    #[test]
    fn version_skew_decision_matrix() {
        use super::{DEGRADED_REALERT_AFTER, version_skew_decision};
        let t0 = std::time::Instant::now();
        let grace = Duration::from_secs(60 * 60);
        let re = DEGRADED_REALERT_AFTER;

        // Matched: no skew.
        assert_eq!(
            version_skew_decision("0.4.18", Some("0.4.18"), None, None, grace, re, t0),
            (None, false)
        );
        // Peer version unknown (pre-versioning peer / not stamped): never a skew.
        assert_eq!(
            version_skew_decision("0.4.18", None, None, None, grace, re, t0),
            (None, false)
        );
        // Skew just observed: start the clock, stay quiet inside the upgrade window.
        assert_eq!(
            version_skew_decision("0.4.18", Some("0.4.17"), None, None, grace, re, t0),
            (Some(t0), false)
        );
        // Still within the grace window (30 min): quiet.
        assert!(
            !version_skew_decision(
                "0.4.18",
                Some("0.4.17"),
                Some(t0),
                None,
                grace,
                re,
                t0 + Duration::from_secs(30 * 60)
            )
            .1
        );
        // Skew outlived the window: fire.
        let past = t0 + Duration::from_secs(61 * 60);
        assert!(version_skew_decision("0.4.18", Some("0.4.17"), Some(t0), None, grace, re, past).1);
        // Alerted, within the re-alert cadence: quiet.
        assert!(
            !version_skew_decision(
                "0.4.18",
                Some("0.4.17"),
                Some(t0),
                Some(past),
                grace,
                re,
                past + Duration::from_secs(60)
            )
            .1
        );
        // Alerted, cadence elapsed: fire again.
        assert!(
            version_skew_decision(
                "0.4.18",
                Some("0.4.17"),
                Some(t0),
                Some(past),
                grace,
                re,
                past + re
            )
            .1
        );
        // Resolved (upgrade completed, versions match): reset, no fire.
        assert_eq!(
            version_skew_decision(
                "0.4.18",
                Some("0.4.18"),
                Some(t0),
                Some(past),
                grace,
                re,
                past
            ),
            (None, false)
        );
    }

    #[test]
    fn resync_decision_matrix() {
        use super::{DEGRADED_REALERT_AFTER, ResyncAction, resync_decision};
        let t0 = std::time::Instant::now();
        let stall = Duration::from_secs(20 * 60);
        let re = DEGRADED_REALERT_AFTER;

        // Not syncing, never alerted: nothing.
        assert_eq!(
            resync_decision(false, None, None, None, false, None, stall, re, t0).action,
            ResyncAction::None
        );
        // First sample of an episode: advancing, start the clock, no alert.
        let o = resync_decision(true, Some(10.0), None, None, false, None, stall, re, t0);
        assert_eq!(o.action, ResyncAction::None);
        assert_eq!((o.last_done, o.stall_since), (Some(10.0), Some(t0)));
        // Advancing (done rose): clock resets to now, no alert.
        let t1 = t0 + Duration::from_secs(120);
        let o = resync_decision(
            true,
            Some(10.5),
            Some(10.0),
            Some(t0),
            false,
            None,
            stall,
            re,
            t1,
        );
        assert_eq!(o.action, ResyncAction::None);
        assert_eq!(o.stall_since, Some(t1));
        // Frozen but within the window: hold, keep the original stall origin.
        let o = resync_decision(
            true,
            Some(10.5),
            Some(10.5),
            Some(t0),
            false,
            None,
            stall,
            re,
            t0 + Duration::from_secs(10 * 60),
        );
        assert_eq!(o.action, ResyncAction::Hold);
        assert_eq!(o.stall_since, Some(t0));
        // Frozen past the window: stalled, fire.
        let t3 = t0 + Duration::from_secs(21 * 60);
        assert_eq!(
            resync_decision(
                true,
                Some(10.5),
                Some(10.5),
                Some(t0),
                false,
                None,
                stall,
                re,
                t3
            )
            .action,
            ResyncAction::Stalled
        );
        // Already alerted, within the re-alert cadence: hold (no spam).
        assert_eq!(
            resync_decision(
                true,
                Some(10.5),
                Some(10.5),
                Some(t0),
                true,
                Some(t3),
                stall,
                re,
                t3 + Duration::from_secs(60)
            )
            .action,
            ResyncAction::Hold
        );
        // Already alerted, cadence elapsed: stalled again.
        assert_eq!(
            resync_decision(
                true,
                Some(10.5),
                Some(10.5),
                Some(t0),
                true,
                Some(t3),
                stall,
                re,
                t3 + re
            )
            .action,
            ResyncAction::Stalled
        );
        // Resumed advancing after an alert: one clear.
        assert_eq!(
            resync_decision(
                true,
                Some(11.0),
                Some(10.5),
                Some(t0),
                true,
                Some(t3),
                stall,
                re,
                t3 + Duration::from_secs(300)
            )
            .action,
            ResyncAction::Clear
        );
        // Resync ended after an alert: one clear.
        assert_eq!(
            resync_decision(
                false,
                None,
                Some(10.5),
                Some(t0),
                true,
                Some(t3),
                stall,
                re,
                t3
            )
            .action,
            ResyncAction::Clear
        );
    }

    #[test]
    fn capacity_decision_matrix() {
        use CapacityAction::*;
        let now = std::time::Instant::now();
        let realert = Duration::from_secs(24 * 3600);
        let recent = Some(now - Duration::from_secs(60));
        let old = Some(now - (realert + Duration::from_secs(1)));
        // Unreadable: never guess.
        assert_eq!(
            capacity_decision(Option::None, 80, 95, 0, Option::None, realert, now),
            None
        );
        // Below warn, nothing alerted: nothing.
        assert_eq!(
            capacity_decision(Some(50), 80, 95, 0, Option::None, realert, now),
            None
        );
        // Below warn but was alerting: clear.
        assert_eq!(
            capacity_decision(Some(50), 80, 95, 1, recent, realert, now),
            Clear
        );
        // Cross into warn: alert now.
        assert_eq!(
            capacity_decision(Some(85), 80, 95, 0, Option::None, realert, now),
            Warn
        );
        // Still warn, alerted recently: hold.
        assert_eq!(
            capacity_decision(Some(85), 80, 95, 1, recent, realert, now),
            Hold
        );
        // Still warn, past the re-alert cadence: re-warn.
        assert_eq!(
            capacity_decision(Some(85), 80, 95, 1, old, realert, now),
            Warn
        );
        // Escalate warn -> critical immediately, even if alerted recently.
        assert_eq!(
            capacity_decision(Some(97), 80, 95, 1, recent, realert, now),
            Critical
        );
        // Still critical, recent: hold.
        assert_eq!(
            capacity_decision(Some(97), 80, 95, 2, recent, realert, now),
            Hold
        );
        // De-escalate critical -> warn (level change): announce the new level.
        assert_eq!(
            capacity_decision(Some(85), 80, 95, 2, recent, realert, now),
            Warn
        );
        // Threshold boundaries: warn at exactly 80, critical at exactly 95.
        assert_eq!(
            capacity_decision(Some(80), 80, 95, 0, Option::None, realert, now),
            Warn
        );
        assert_eq!(
            capacity_decision(Some(95), 80, 95, 0, Option::None, realert, now),
            Critical
        );
    }

