    #[tokio::test(start_paused = true)]
    async fn boundary_failure_holds_both_copies_and_retries_on_its_own_pace() {
        let drbd = std::sync::Arc::new(MockDrbd::new(online_with_peer()));
        drbd.set_handshake(Some(lb_fork_lost()));
        let iscsi_stop = std::sync::Arc::new(AtomicBool::new(false));
        let mut fake =
            crate::loser_boundary::fake::FakeGuests::with_guests(vec![lb_guest(1, "web")]);
        fake.scan_fails = true;
        let fake = std::sync::Arc::new(fake);
        let (mut sm, marker) = lb_machine("hold", drbd.clone(), fake.clone(), iscsi_stop.clone());

        sm.resolve_split_brain().await;
        assert!(
            !drbd.calls().iter().any(|c| matches!(
                *c,
                "connect_discard" | "secondary" | "resume_io" | "disconnect"
            )),
            "nothing may be discarded or withdrawn on a boundary hold: {:?}",
            drbd.calls()
        );
        assert!(
            !iscsi_stop.load(Ordering::Relaxed),
            "the target keeps serving during the hold"
        );
        assert!(
            !fake.calls().iter().any(|c| c.starts_with("stop")),
            "no guest stopped without a readable local scan"
        );
        assert!(sm.boundary_retry_at.is_some());

        // An immediate re-entry does not re-run the boundary (paced retry).
        let before = fake.calls().len();
        sm.resolve_split_brain().await;
        assert_eq!(fake.calls().len(), before);
        assert!(!drbd.calls().contains(&"connect_discard"));

        // The episode ends by hand (operator discard, flip, sweep): the next
        // episode alerts and retries afresh instead of staying silent.
        assert!(sm.boundary_hold_alerted || cfg!(test));
        // (This test's own hold alert sits in the held queue: XAPI is absent.)
        let _ = xapi::drop_held_alert("twinstor_split_brain", "boundary-hold");
        sm.boundary_hold_alerted = true;
        // A Clear whose hold alert was already delivered (nothing held to
        // withdraw) keeps the latch: a later hold of this episode is not
        // re-sent every retry.
        sm.withdraw_boundary_hold_alert();
        assert!(sm.boundary_hold_alerted);
        sm.clear_yield_state();
        assert!(
            !sm.boundary_hold_alerted && sm.boundary_retry_at.is_none() && !sm.sb_diverged_alerted
        );
        let _ = std::fs::remove_file(&marker);
        let _ = std::fs::remove_file(&sm.boundary_path);
    }

    #[tokio::test(start_paused = true)]
    async fn lineage_hold_restarts_guests_on_winner_unknown_hold_does_not() {
        for (lineage, expect_start) in [(true, true), (false, false)] {
            let drbd = std::sync::Arc::new(MockDrbd::new(online_with_peer()));
            drbd.set_handshake(if lineage { Some(lb_fork_lost()) } else { None });
            // "web" stops; "db" survives every stop, so hold after "web" is down.
            let mut fake = crate::loser_boundary::fake::FakeGuests::with_guests(vec![
                lb_guest(1, "web"),
                lb_guest(2, "db"),
            ]);
            fake.unkillable = vec![lb_guest(2, "db").uuid];
            let fake = std::sync::Arc::new(fake);
            let tag = format!("early-{lineage}");
            let (mut sm, marker) = lb_machine(
                &tag,
                drbd.clone(),
                fake.clone(),
                std::sync::Arc::new(AtomicBool::new(false)),
            );
            if !lineage {
                // Unreadable lineage reaches the loser path through the role
                // election; force it so the test exercises the Unknown evidence.
                sm.sb_fork_evidence = crate::loser_boundary::ForkEvidence::Unknown;
                sm.resolve_as_loser(
                    &sm.marker_path.clone(),
                    true,
                    crate::loser_boundary::ForkEvidence::Unknown,
                )
                .await;
                for _ in 0..4 {
                    sm.boundary_retry_at = None;
                    sm.resolve_as_loser(
                        &sm.marker_path.clone(),
                        true,
                        crate::loser_boundary::ForkEvidence::Unknown,
                    )
                    .await;
                }
            } else {
                for _ in 0..5 {
                    sm.boundary_retry_at = None;
                    sm.resolve_split_brain().await;
                }
            }
            assert!(
                !drbd.calls().contains(&"connect_discard"),
                "a hold never discards"
            );
            for _ in 0..3 {
                sm.boundary_restart_retry_at = None;
                sm.check_boundary_restarts().await;
            }
            assert_eq!(
                fake.calls().contains(&"start web on peer".to_string()),
                expect_start,
                "lineage={lineage}: {:?}",
                fake.calls()
            );
            let _ = std::fs::remove_file(&marker);
            let _ = std::fs::remove_file(&sm.boundary_path);
        }
    }

    #[test]
    fn loser_teardown_logs_the_loopback_out_before_resuming_frozen_io() {
        // Writes a fence-peer suspend froze on the doomed copy must not
        // complete through the local path: the loopback goes first.
        let pos = |s: TeardownStep| LOSER_TEARDOWN.iter().position(|&x| x == s).unwrap();
        assert!(pos(TeardownStep::LogoutLoopback) < pos(TeardownStep::ResumeIo));
    }

