    #[tokio::test(start_paused = true)]
    async fn owed_restarts_survive_daemon_restart_until_episode_end() {
        use crate::loser_boundary::{Phase, Record, Store};
        let drbd = std::sync::Arc::new(MockDrbd::new(online_with_peer()));
        let fake = std::sync::Arc::new(crate::loser_boundary::fake::FakeGuests::default());
        let (mut sm, marker) = lb_machine(
            "resume",
            drbd,
            fake.clone(),
            std::sync::Arc::new(AtomicBool::new(false)),
        );
        // A previous daemon life stopped "web" and died before the discard.
        Store::new(&sm.boundary_path)
            .save(&Record {
                key: "K".into(),
                phase: Phase::Stopped,
                early_restart: false,
                open: true,
                agent_restarted: false,
                host_disabled: false,
                owed: vec![crate::loser_boundary::Owed {
                    guest: lb_guest(1, "web"),
                    stop_tries: 1,
                    start_tries: 0,
                }],
                leaked: Vec::new(),
            })
            .unwrap();
        sm.boundary_restart_pending = std::path::Path::new(&sm.boundary_path).exists();
        assert!(sm.boundary_restart_pending);

        // Episode still open (marker present), discard not started: no start.
        sm.check_boundary_restarts().await;
        assert!(fake.calls().is_empty(), "{:?}", fake.calls());

        // The tmpfs marker vanishing (a reboot does that) is not an episode
        // end: still no start before the pair positively converged.
        std::fs::remove_file(&marker).unwrap();
        sm.boundary_restart_retry_at = None;
        sm.check_boundary_restarts().await;
        assert!(fake.calls().is_empty(), "{:?}", fake.calls());

        // Converged (Connected, both UpToDate): the owed start runs.
        sm.boundary_close_episode();
        sm.boundary_restart_retry_at = None;
        sm.check_boundary_restarts().await;
        // The episode ended without this node discarding: both copies are the
        // same again and this host, which kept its data, takes it back.
        assert_eq!(fake.calls(), ["start web on this"]);
        assert!(!sm.boundary_restart_pending);
    }

    #[tokio::test(start_paused = true)]
    async fn flip_to_winner_keeps_owed_restarts_and_skips_post_discard_check() {
        // The peer refused the discard and this keeper claims the win: the
        // flip revokes the restarts on the peer. Marking the record discarding
        // afterwards would send them back to the peer and run the post-discard
        // check on a node that discarded nothing.
        let mut status = online_with_peer();
        status.connection = ConnectionState::StandAlone;
        let drbd = std::sync::Arc::new(MockDrbd::new(status));
        drbd.set_handshake(Some(lb_fork_lost()));
        let fake = std::sync::Arc::new(crate::loser_boundary::fake::FakeGuests::with_guests(vec![
            lb_guest(1, "web"),
        ]));
        let (mut sm, marker) = lb_machine(
            "flip-round",
            drbd.clone(),
            fake.clone(),
            std::sync::Arc::new(AtomicBool::new(false)),
        );
        sm.resolve_split_brain().await;
        assert!(sm.discard_round_flipped, "{:?}", drbd.calls());
        let r = crate::loser_boundary::Store::new(&sm.boundary_path)
            .load()
            .unwrap()
            .unwrap();
        assert_eq!(
            r.phase,
            crate::loser_boundary::Phase::Stopped,
            "not discarding"
        );
        assert!(!r.early_restart);
        assert_eq!(
            crate::loser_boundary::restart_host(&r),
            crate::loser_boundary::RestartHost::ThisHost
        );
        let calls = fake.calls();
        let last_confirm = calls.iter().rposition(|c| c == "taps").unwrap();
        assert!(
            !calls[last_confirm..].iter().any(|c| c == "scan"),
            "no post-discard check: {calls:?}"
        );
        sm.boundary_restart_retry_at = None;
        sm.check_boundary_restarts().await;
        assert!(
            !fake
                .calls()
                .iter()
                .any(|c| c.starts_with("start web on peer")),
            "{:?}",
            fake.calls()
        );
        let _ = std::fs::remove_file(&marker);
        let _ = std::fs::remove_file(&sm.boundary_path);
    }

