    #[test]
    fn boundary_alerts_name_the_vms_and_the_failed_step() {
        let stopped = vec![lb_guest(1, "web"), lb_guest(2, "")];
        let b = boundary_discard_alert_body(&stopped, "node-b");
        assert!(
            b.contains("web")
                && b.contains("00000002-0000-4000-8000-000000000000")
                && b.contains("node-b"),
            "{b}"
        );
        use crate::loser_boundary::Step;
        let h = boundary_hold_alert_body(Step::ConfirmStopped, "still running: db", &stopped, true);
        assert!(
            h.contains("nothing was discarded")
                && h.contains("still running: db")
                && h.contains("twinstor discard-and-resync")
                && h.contains("being started on the winner")
                && h.contains("once those VMs are stopped"),
            "{h}"
        );
        let u = boundary_hold_alert_body(Step::LocalScan, "y", &stopped, false);
        assert!(
            u.contains("kept stopped because the divergence could not be read")
                && u.contains("stopping the VMs does not help")
                && !u.contains("once those VMs are stopped"),
            "{u}"
        );
        let r = boundary_hold_alert_body(Step::Record, "disk full", &[], true);
        assert!(
            r.contains("/var/lib/twinstor is writable")
                && !r.contains("once those VMs are stopped"),
            "{r}"
        );
        // The bring-up winner keeps its copy: never sent to discard it.
        let w =
            winner_boundary_hold_alert_body(Step::ConfirmStopped, "still running: web", &stopped);
        assert!(
            w.contains("won the resolution")
                && w.contains("Do not run `twinstor discard-and-resync`")
                && w.contains("still running: web")
                && w.contains("started again on this host once the pair has converged")
                && !w.contains("run `twinstor discard-and-resync` here")
                && !w.contains("lost the resolution"),
            "{w}"
        );
        // Its disk-handle step closes onto the peer's copy: never told the own-path rule.
        let wt =
            winner_boundary_hold_alert_body(Step::Tapdisks, "still open after destroy", &stopped);
        assert!(
            wt.contains("own target is not exported or its own portal is not the active")
                && wt.contains("DP.destroy")
                && !wt.contains("active storage path is the peer's portal")
                && !wt.contains("force-shutdown every VM"),
            "{wt}"
        );
        let rb = boundary_restart_alert_body(
            &[(lb_guest(1, "web"), "node-b".into())],
            &[lb_guest(2, "db")],
        );
        assert!(
            rb.contains("started on node-b: web") && rb.contains("already running: db"),
            "{rb}"
        );
        // Guests started on different hosts are each named under their own host.
        let rb2 = boundary_restart_alert_body(
            &[
                (lb_guest(1, "web"), "node-b".into()),
                (lb_guest(3, "mail"), "node-a (this host)".into()),
                (lb_guest(4, "dns"), "node-b".into()),
            ],
            &[],
        );
        assert!(
            rb2.contains("started on node-b: web, dns")
                && rb2.contains("started on node-a (this host): mail")
                && !rb2.contains("already running"),
            "{rb2}"
        );
    }

    #[test]
    fn yield_latch_follows_the_boundary_lift() {
        let (old, new) = (0xDC0F_2700_E625_704A_u64, 0xD18F_7338_6EAD_3FCE_u64);
        assert!(relatch_yield_needed(Some(Some(old)), old, new));
        assert!(
            relatch_yield_needed(Some(Some(old | 1)), old, new),
            "bit 0 is not identity"
        );
        assert!(
            !relatch_yield_needed(Some(Some(old)), old, old | 1),
            "generation did not move"
        );
        assert!(
            !relatch_yield_needed(Some(Some(new)), old, new),
            "latch bound elsewhere"
        );
        assert!(
            !relatch_yield_needed(Some(None), old, new),
            "unknown latch stays as is"
        );
        assert!(
            !relatch_yield_needed(None, old, new),
            "no latch, nothing to follow"
        );
        // After the re-bind the claim is Y for the new generation, never G.
        assert_eq!(
            beacon_claim_ext(Some(Some(new)), None, Some(new), true, None),
            Some(crate::peer_signal::ForkClaim::Yielded(new))
        );
    }

    #[test]
    fn protected_vm_start_cap_tries_never_failed_first() {
        let fails = |u: &str| match u {
            "a" => 3,
            "b" => 1,
            _ => 0,
        };
        let mut v: Vec<String> = ["a", "b", "c", "d", "e"]
            .iter()
            .map(|s| s.to_string())
            .collect();
        assert_eq!(cap_protected_vm_starts(&mut v, fails, 3), 2);
        assert_eq!(v, ["c", "d", "e"]);
        let mut f: Vec<String> = ["a", "b", "c"].iter().map(|s| s.to_string()).collect();
        assert_eq!(cap_protected_vm_starts(&mut f, fails, 2), 1);
        assert_eq!(f, ["c", "b"]);
        let mut w: Vec<String> = vec!["x".into()];
        assert_eq!(cap_protected_vm_starts(&mut w, |_| 0, 3), 0);
        assert_eq!(w, ["x"]);
    }

