    #[test]
    fn freeze_claims_keep_their_precedence() {
        use crate::peer_signal::ForkClaim;
        let cur = 0xAAAA_0000_0000_0010;
        assert_eq!(
            beacon_claim_ext(None, None, Some(cur), true, Some(Some(7))),
            Some(ForkClaim::GiveWay(7))
        );
        assert_eq!(
            beacon_claim_ext(None, None, Some(cur), true, None),
            Some(ForkClaim::FrozenGuests(cur))
        );
        assert_eq!(
            beacon_claim_ext(None, None, None, true, None),
            None,
            "no generation, no G"
        );
        assert_eq!(
            beacon_claim_ext(Some(Some(cur)), None, Some(cur), true, None),
            Some(ForkClaim::Yielded(cur))
        );
        assert_eq!(
            beacon_claim_ext(None, Some(Some(9)), Some(cur), true, None),
            Some(ForkClaim::Won(9))
        );
        assert_eq!(
            beacon_claim_ext(None, None, Some(cur), false, Some(None)),
            None,
            "R needs a generation"
        );
    }

    /// A freeze-mode node at StandAlone after a split with no split-brain
    /// marker (the frozen copy is merely behind). `frozen`: this node yielded
    /// with guests and its I/O is suspended.
    fn freeze_node(
        tag: &str,
        claim: crate::peer_signal::PeerClaim,
        frozen: bool,
    ) -> (StateMachine, std::sync::Arc<MockDrbd>) {
        let (mut sm, drbd) = wedge_survivor(tag, claim);
        let _ = std::fs::remove_file(&sm.marker_path);
        std::fs::write(&sm.peer_fs_freeze_path, "").unwrap();
        for p in [
            &sm.fs_freeze_off_path,
            &sm.give_way_path,
            &sm.split_guests_path,
        ] {
            let _ = std::fs::remove_file(p);
        }
        if frozen {
            std::fs::write(&sm.yield_path, "yielded\n").unwrap();
            let mut st = drbd.status.lock().unwrap().clone();
            st.suspended_user = true;
            drbd.set_status(st);
            sm.guests =
                std::sync::Arc::new(crate::loser_boundary::fake::FakeGuests::with_guests(vec![
                    lb_guest(1, "web"),
                ]));
        }
        assert!(sm.fs_freeze());
        (sm, drbd)
    }

    fn freeze_cleanup(sm: &StateMachine) {
        cleanup(sm);
        for p in [
            &sm.fs_freeze_off_path,
            &sm.peer_fs_freeze_path,
            &sm.fs_freeze_flag_path,
            &sm.give_way_path,
            &sm.split_guests_path,
        ] {
            let _ = std::fs::remove_file(p);
        }
        let _ = std::fs::remove_file(give_way_taken_path(&sm.give_way_path));
    }

    #[tokio::test(start_paused = true)]
    async fn freeze_guestless_survivor_gives_way_announces_once_secondary() {
        use crate::peer_signal::{ForkClaim, PeerClaim};
        let hs = wedge_fork();
        let (mut sm, drbd) = freeze_node(
            "fz-giveway",
            PeerClaim::Claim(ForkClaim::FrozenGuests(hs.peer.current)),
            false,
        );
        let status = drbd.status.lock().unwrap().clone();
        assert!(sm.freeze_standalone_step(&status).await);
        let calls = drbd.calls();
        assert!(calls.contains(&"secondary"), "demoted; calls: {calls:?}");
        assert!(
            !calls.contains(&"connect_discard") && !calls.contains(&"connect"),
            "no offer before the frozen peer's new generation; calls: {calls:?}"
        );
        assert!(
            !calls.contains(&"force_primary") && !calls.contains(&"primary"),
            "calls: {calls:?}"
        );
        assert_eq!(
            read_fork_record(&sm.give_way_path),
            Some(Some(hs.peer.current)),
            "R once Secondary"
        );
        assert!(sm.freeze_give_way_gen.is_none());
        assert_eq!(
            read_fork_record(&sm.win_path),
            None,
            "the frozen peer's W is acceptance, never a flip"
        );
        // Back at StandAlone, Secondary, the peer still frozen (G): hold, no offer.
        let mut st = drbd.status.lock().unwrap().clone();
        st.role = Role::Secondary;
        drbd.set_status(st.clone());
        assert!(sm.freeze_standalone_step(&st).await);
        assert!(
            !drbd.calls().contains(&"connect_discard"),
            "calls: {:?}",
            drbd.calls()
        );
        assert!(
            std::path::Path::new(&sm.give_way_path).exists(),
            "still giving way"
        );
        // The peer took it (W, new generation): offer, and again on every pass.
        sm.test_peer_claim = PeerClaim::Claim(ForkClaim::Won(hs.local.current));
        assert!(sm.freeze_standalone_step(&st).await);
        assert!(sm.freeze_standalone_step(&st).await);
        assert_eq!(
            drbd.calls()
                .iter()
                .filter(|c| **c == "connect_discard")
                .count(),
            2
        );
        freeze_cleanup(&sm);
    }

    #[tokio::test(start_paused = true)]
    async fn freeze_waiting_node_connects_only_to_frozen_peer() {
        use crate::peer_signal::{ForkClaim, PeerClaim};
        let hs = wedge_fork();
        // No claim yet (the peer still deciding): stay StandAlone.
        let (mut sm, drbd) = freeze_node("fz-noconn", PeerClaim::Unreachable, true);
        let status = drbd.status.lock().unwrap().clone();
        assert!(sm.freeze_standalone_step(&status).await);
        assert!(
            !drbd.calls().contains(&"connect"),
            "calls: {:?}",
            drbd.calls()
        );
        // The peer frozen with guests too (both wrote nothing): connect plainly.
        sm.test_peer_claim = PeerClaim::Claim(ForkClaim::FrozenGuests(hs.peer.current));
        assert!(sm.freeze_standalone_step(&status).await);
        assert!(
            drbd.calls().contains(&"connect") && !drbd.calls().contains(&"connect_discard"),
            "calls: {:?}",
            drbd.calls()
        );
        freeze_cleanup(&sm);
    }

    #[tokio::test(start_paused = true)]
    async fn freeze_frozen_node_leaves_a_connect_when_the_peer_gives_way() {
        use crate::peer_signal::{ForkClaim, PeerClaim};
        let hs = wedge_fork();
        let (mut sm, drbd) = freeze_node(
            "fz-leave",
            PeerClaim::Claim(ForkClaim::GiveWay(hs.local.current)),
            true,
        );
        let mut st = drbd.status.lock().unwrap().clone();
        st.connection = ConnectionState::Connecting;
        drbd.set_status(st);
        sm.freeze_tick().await;
        assert!(
            drbd.calls().contains(&"disconnect"),
            "calls: {:?}",
            drbd.calls()
        );
        assert!(
            !drbd.calls().contains(&"new_current_uuid"),
            "rotates at StandAlone; calls: {:?}",
            drbd.calls()
        );
        // Once it took the give-way, a connect is its own: left alone.
        let (mut sm2, drbd2) = freeze_node(
            "fz-leave2",
            PeerClaim::Claim(ForkClaim::GiveWay(hs.local.current)),
            true,
        );
        write_fork_record(&sm2.win_path, Some(hs.peer.current));
        let mut st = drbd2.status.lock().unwrap().clone();
        st.connection = ConnectionState::Connecting;
        drbd2.set_status(st);
        sm2.freeze_tick().await;
        assert!(
            !drbd2.calls().contains(&"disconnect"),
            "calls: {:?}",
            drbd2.calls()
        );
        freeze_cleanup(&sm);
        freeze_cleanup(&sm2);
    }

    #[tokio::test(start_paused = true)]
    async fn freeze_give_way_resumes_at_budget_and_never_discards() {
        use crate::peer_signal::{ForkClaim, PeerClaim};
        let hs = wedge_fork();
        let (mut sm, drbd) = freeze_node(
            "fz-keepbudget",
            PeerClaim::Claim(ForkClaim::GiveWay(hs.local.current)),
            true,
        );
        write_fork_record(&sm.win_path, Some(hs.peer.current));
        sm.frozen_since =
            std::time::Instant::now().checked_sub(FREEZE_GUEST_BUDGET + Duration::from_secs(1));
        sm.freeze_tick().await;
        let calls = drbd.calls();
        assert!(calls.contains(&"resume_io"), "calls: {calls:?}");
        assert!(
            !calls.contains(&"secondary") && !calls.contains(&"connect_discard"),
            "calls: {calls:?}"
        );
        assert!(read_fork_record(&sm.latch_path).is_none(), "no loser latch");
        assert!(
            !std::path::Path::new(&sm.yield_path).exists(),
            "no longer frozen"
        );
        // Resumed, StandAlone, the peer still offering: connect for the discard to land.
        let mut st = drbd.status.lock().unwrap().clone();
        st.suspended_user = false;
        drbd.set_status(st.clone());
        assert!(sm.freeze_standalone_step(&st).await);
        assert!(
            drbd.calls().contains(&"connect"),
            "calls: {:?}",
            drbd.calls()
        );
        freeze_cleanup(&sm);
    }

    #[tokio::test(start_paused = true)]
    async fn freeze_giver_offers_in_a_later_round_and_from_bring_up() {
        use crate::peer_signal::{ForkClaim, PeerClaim};
        let hs = wedge_fork();
        // A later resolver round (not the call that starts the give-way):
        // the split-brain proves the peer's new generation, offer at once.
        let (mut sm, drbd) = freeze_node(
            "fz-later",
            PeerClaim::Claim(ForkClaim::Won(hs.local.current)),
            false,
        );
        write_fork_record(&sm.give_way_path, Some(hs.peer.current));
        let marker = sm.marker_path.clone();
        sm.resolve_as_loser(
            &marker,
            true,
            crate::loser_boundary::ForkEvidence::NotDiverged,
        )
        .await;
        assert!(
            drbd.calls().contains(&"connect_discard"),
            "calls: {:?}",
            drbd.calls()
        );
        freeze_cleanup(&sm);
        // Bring-up after a daemon restart, StandAlone, Secondary, the peer took it.
        let (mut sm, drbd) = freeze_node(
            "fz-init",
            PeerClaim::Claim(ForkClaim::Won(hs.local.current)),
            false,
        );
        write_fork_record(&sm.give_way_path, Some(hs.peer.current));
        let mut st = drbd.status.lock().unwrap().clone();
        st.role = Role::Secondary;
        drbd.set_status(st);
        sm.set_state(NodeState::Init);
        sm.freeze_tick().await;
        assert!(
            drbd.calls().contains(&"connect_discard"),
            "calls: {:?}",
            drbd.calls()
        );
        assert!(sm.give_way_taken);
        freeze_cleanup(&sm);
    }

    #[tokio::test(start_paused = true)]
    async fn kept_copy_frozen_at_reconnect_released_on_next_passes() {
        use crate::peer_signal::PeerClaim;
        let hs = wedge_fork();
        let (mut sm, drbd) = freeze_node("fz-keepclear", PeerClaim::Unreachable, true);
        write_fork_record(&sm.win_path, Some(hs.peer.current));
        let mut st = drbd.status.lock().unwrap().clone();
        st.connection = ConnectionState::Connected;
        st.replication = Some(crate::drbd::Replication::WFBitMap);
        st.peer_disk = Some(DiskState::Outdated);
        drbd.set_status(st.clone());
        sm.connected_since =
            std::time::Instant::now().checked_sub(LEFTOVER_LIFT_STABLE + Duration::from_secs(1));
        // The reconnect: one release pass, then the episode is closed.
        sm.release_winner_freeze().await;
        sm.clear_yield_state_after_keep().await;
        assert!(
            std::path::Path::new(&sm.yield_path).exists(),
            "still frozen: kept"
        );
        assert!(!drbd.calls().contains(&"resume_io"));
        // The tick's next passes finish the release.
        sm.release_winner_freeze().await;
        sm.release_winner_freeze().await;
        assert!(
            drbd.calls().contains(&"resume_io"),
            "calls: {:?}",
            drbd.calls()
        );
        // Freeze mode, the marker lost anyway: a sync source still resumes.
        let (mut sm3, drbd3) = freeze_node("fz-keepclear3", PeerClaim::Unreachable, true);
        let _ = std::fs::remove_file(&sm3.yield_path);
        drbd3.set_status(st.clone());
        sm3.connected_since =
            std::time::Instant::now().checked_sub(LEFTOVER_LIFT_STABLE + Duration::from_secs(1));
        sm3.release_winner_freeze().await;
        sm3.release_winner_freeze().await;
        assert!(
            drbd3.calls().contains(&"resume_io"),
            "calls: {:?}",
            drbd3.calls()
        );
        freeze_cleanup(&sm3);
        // Not frozen: cleared.
        let (mut sm2, drbd2) = freeze_node("fz-keepclear2", PeerClaim::Unreachable, false);
        std::fs::write(&sm2.yield_path, "yielded\n").unwrap();
        write_fork_record(&sm2.win_path, Some(1));
        let _ = drbd2;
        sm2.clear_yield_state_after_keep().await;
        assert!(!std::path::Path::new(&sm2.yield_path).exists());
        assert!(read_fork_record(&sm2.win_path).is_none());
        freeze_cleanup(&sm);
        freeze_cleanup(&sm2);
    }

    #[tokio::test(start_paused = true)]
    async fn freeze_fencing_follows_the_marker_from_the_live_policy() {
        use crate::peer_signal::PeerClaim;
        let (mut sm, drbd) = freeze_node("fz-fencing", PeerClaim::Unreachable, false);
        *drbd.fencing.lock().unwrap() = Some("resource-only".into());
        sm.enforce_freeze_fencing().await;
        assert_eq!(
            drbd.fencing.lock().unwrap().as_deref(),
            Some("resource-and-stonith")
        );
        assert!(
            std::path::Path::new(&sm.fs_freeze_flag_path).exists(),
            "the handler's flag follows"
        );
        // A restarted daemon over a policy its predecessor set, freeze mode
        // now off (the peer stopped advertising it): restored all the same.
        let _ = std::fs::remove_file(&sm.peer_fs_freeze_path);
        sm.enforce_freeze_fencing().await;
        assert_eq!(
            drbd.fencing.lock().unwrap().as_deref(),
            Some("resource-only")
        );
        assert!(!std::path::Path::new(&sm.fs_freeze_flag_path).exists());
        // Freeze mode off: any other policy (a bounce's dont-care) is left alone.
        *drbd.fencing.lock().unwrap() = Some("dont-care".into());
        sm.enforce_freeze_fencing().await;
        assert_eq!(drbd.fencing.lock().unwrap().as_deref(), Some("dont-care"));
        freeze_cleanup(&sm);
    }

