        *drbd.fencing.lock().unwrap() = Some("resource-and-stonith".into());
        let mut st = drbd.status.lock().unwrap().clone();
        st.suspended_user = true;
        drbd.set_status(st);
        sm.restore_freeze_policy_on_shutdown().await;
