    #[tokio::test(start_paused = true)]
    async fn freeze_mode_is_on_by_default_and_needs_both_nodes() {
        use crate::peer_signal::PeerClaim;
        let (mut sm, drbd) = freeze_node("fz-default", PeerClaim::Unreachable, false);
        // Fate-shared, no opt-out, the peer advertised it: engaged.
        assert!(sm.fs_freeze_wanted() && sm.fs_freeze());
        // The peer never advertised it (an older release mid-upgrade, or an
        // opted-out peer): this node wants it but keeps the pre-freeze policy.
        let _ = std::fs::remove_file(&sm.peer_fs_freeze_path);
        assert!(sm.fs_freeze_wanted() && !sm.fs_freeze());
        *drbd.fencing.lock().unwrap() = Some("resource-only".into());
        sm.enforce_freeze_fencing().await;
        assert_eq!(
            drbd.fencing.lock().unwrap().as_deref(),
            Some("resource-only")
        );
        // Opted out here: neither wanted (so the peer stays off too) nor engaged.
        std::fs::write(&sm.peer_fs_freeze_path, "").unwrap();
        std::fs::write(&sm.fs_freeze_off_path, "").unwrap();
        assert!(!sm.fs_freeze_wanted() && !sm.fs_freeze());
        // Never on an arbitrated pool.
        let _ = std::fs::remove_file(&sm.fs_freeze_off_path);
        sm.arbitrated = true;
        assert!(!sm.fs_freeze_wanted() && !sm.fs_freeze());
        freeze_cleanup(&sm);
    }

    #[tokio::test(start_paused = true)]
    async fn a_frozen_freeze_mode_copy_keeps_the_tick_off_xapi() {
        use crate::peer_signal::PeerClaim;
        let (mut sm, drbd) = freeze_node("fz-quiet", PeerClaim::Unreachable, true);
        assert!(
            sm.io_frozen_now().await,
            "frozen I/O in freeze mode quiets the XAPI steps"
        );
        // Re-read at most once a second, so the per-step checks stay cheap.
        let mut st = drbd.status.lock().unwrap().clone();
        st.suspended_user = false;
        drbd.set_status(st);
        assert!(sm.io_frozen_now().await, "cached within the second");
        sm.io_frozen_read = None; // the second has passed
        assert!(!sm.io_frozen_now().await, "resumed I/O lets them run again");
        // Without freeze mode a suspended copy is the older paths' business.
        let mut st = drbd.status.lock().unwrap().clone();
        st.suspended_user = true;
        drbd.set_status(st);
        let _ = std::fs::remove_file(&sm.peer_fs_freeze_path);
        sm.io_frozen_read = None;
        assert!(!sm.io_frozen_now().await);
        freeze_cleanup(&sm);
    }

    #[tokio::test(start_paused = true)]
    async fn healthy_node_avoids_xapi_early_in_freeze_disconnect() {
        use crate::peer_signal::PeerClaim;
        let (mut sm, drbd) = freeze_node("fz-survquiet", PeerClaim::Unreachable, false);
        let mut st = drbd.status.lock().unwrap().clone();
        st.connection = ConnectionState::Connecting;
        drbd.set_status(st);
        assert!(!sm.io_frozen_now().await);
        assert!(
            sm.xapi_quiet().await,
            "the give-way decision must not wait behind XAPI"
        );
        // A long outage (a dead peer): the XAPI watchdogs run again.
        sm.freeze_disconnect_since =
            std::time::Instant::now().checked_sub(SB_FRESH_WINDOW + Duration::from_secs(1));
        sm.io_frozen_read = None;
        assert!(!sm.xapi_quiet().await);
        // Connected again: the window resets.
        let mut st = drbd.status.lock().unwrap().clone();
        st.connection = ConnectionState::Connected;
        drbd.set_status(st);
        sm.io_frozen_read = None;
        assert!(!sm.xapi_quiet().await);
        assert!(sm.freeze_disconnect_since.is_none());
        // Without freeze mode nothing changes.
        let _ = std::fs::remove_file(&sm.peer_fs_freeze_path);
        let mut st = drbd.status.lock().unwrap().clone();
        st.connection = ConnectionState::Connecting;
        drbd.set_status(st);
        sm.io_frozen_read = None;
        assert!(!sm.xapi_quiet().await);
        freeze_cleanup(&sm);
    }

