    #[tokio::test(start_paused = true)]
    async fn freeze_give_way_new_generation_resumes_and_connects() {
        use crate::peer_signal::{ForkClaim, PeerClaim};
        let hs = wedge_fork();
        let (mut sm, drbd) = freeze_node(
            "fz-takes",
            PeerClaim::Claim(ForkClaim::GiveWay(hs.local.current)),
            true,
        );
        let status = drbd.status.lock().unwrap().clone();
        assert!(sm.freeze_standalone_step(&status).await);
        let calls = drbd.calls();
        assert!(calls.contains(&"new_current_uuid"), "calls: {calls:?}");
        assert!(
            calls.contains(&"connect") && !calls.contains(&"connect_discard"),
            "calls: {calls:?}"
        );
        assert!(!calls.contains(&"secondary"), "calls: {calls:?}");
        // The new generation first, then the guests resume, then the connect:
        // no frozen request reaches the peer's resync.
        let at = |c: &str| calls.iter().position(|x| *x == c).unwrap();
        assert!(
            at("new_current_uuid") < at("resume_io") && at("resume_io") < at("connect"),
            "calls: {calls:?}"
        );
        assert!(!std::path::Path::new(&sm.yield_path).exists());
        assert_eq!(read_fork_record(&sm.win_path), Some(Some(hs.peer.current)));
        // A second pass does not start yet another generation.
        assert!(sm.freeze_standalone_step(&status).await);
        assert_eq!(
            drbd.calls()
                .iter()
                .filter(|c| **c == "new_current_uuid")
                .count(),
            1
        );
        freeze_cleanup(&sm);
    }

